    imageHint: "Puna'auia coast with Moorea in the background",
    descriptionAdvanced: {
      de: "Puna'auia ist eine prosperierende Gemeinde an der Westküste von Tahiti, etwa 15 Kilometer südlich der Hauptstadt Papeete. Sie gilt als bevorzugtes Wohnviertel und beherbergt die Universität von Französisch-Polynesien, was ihr eine junge und akademische Atmosphäre verleiht. Kulturell ist der Ort durch das Musée de Tahiti et des Îles bedeutend, das in einem Park am Meer liegt und die Geschichte und Bräuche der polynesischen Völker dokumentiert. Die Küstenabschnitte bieten hervorragende Bedingungen zum Surfen und Tauchen, insbesondere am beliebten Strand von Vaiava. Von der Küste aus hat man einen spektakulären Blick auf die Nachbarinsel Moorea, besonders bei Sonnenuntergang. Puna'auia ist zudem ein wichtiges Wirtschaftszentrum mit großen Einkaufszentren und modernen Jachthäfen, die als Ausgangspunkt für Ausflüge in die Lagune dienen, und verbindet modernes Stadtleben mit inseltypischer Gelassenheit.",
      hu: "Puna'auia egy dinamikusan fejlődő település Tahiti nyugati partján, mintegy 15 kilométerre a fővárostól, Papeetétől. Elsősorban elegáns lakónegyedeiről és pezsgő kereskedelmi életéről ismert. Itt található a Francia Polinéziai Egyetem központi kampusza, amely a régió legfontosabb felsőoktatási intézménye. A kultúra kedvelői számára a Tahiti és Szigetek Múzeuma (Musée de Tahiti et des Îles) kínál betekintést a polinéz népek történelmébe, művészetébe és tengerészeti hagyományaiba. A település partjairól, különösen a Vaiava strand környékéről, lenyűgöző kilátás nyílik a szemközti Moorea szigetére. A terület gazdasági központként is funkcionál, számos modern bevásárlóközponttal és kikötővel rendelkezik. Puna'auia ideális választás azoknak, akik a modern kényelmet polinéz vendégszeretettel és gyönyörű természeti környezettel ötvözve keresik Tahiti szigetén.",
      ro: "Puna'auia este o comună rezidențială și comercială importantă situată pe coasta de vest a insulei Tahiti, la mică distanță de Papeete. Localitatea este recunoscută ca fiind centrul academic al Polineziei Franceze, găzduind sediul principal al universității locale. Un punct de atracție major este Muzeul Tahiti și al Insulelor, care oferă o perspectivă detaliată asupra culturii, istoriei și mediului natural al arhipelagului. Plajele din Puna'auia, cum ar fi celebra Plage Vaiava, sunt populare atât pentru relaxare, cât și pentru sporturi nautice. Poziția geografică oferă vederi panoramice superbe asupra insulei vecine Moorea, în special în timpul apusului. Orașul dispune de infrastructură modernă, inclusiv centre comerciale mari și facilități portuare, fiind un punct de plecare ideal pentru explorarea lagunei și a recifelor de corali din apropiere, îmbinând facilitățile urbane cu farmecul tropical.",
      en: "Puna'auia is a thriving coastal commune located on the western side of Tahiti, approximately 15 kilometers south of Papeete. It is widely regarded as one of the island's most desirable residential areas, blending modern convenience with traditional Polynesian charm. The town is home to the University of French Polynesia, establishing it as the educational heart of the territory. Visitors are drawn to the Museum of Tahiti and the Islands, situated in a scenic park, which meticulously archives the ethnographic and natural history of the region. The coastline features beautiful white sand beaches like Vaiava and offers some of the best sunset views overlooking the jagged peaks of nearby Moorea. With its large shopping complexes and marinas, Puna'auia serves as a vital economic hub while remaining a gateway to the island's aquatic adventures, coral reefs, and inland hiking trails.",
      es: "Punaauia se encuentra en la costa oeste de Tahití, al sur de Papeete, y es un lugar residencial y turístico muy popular. El municipio tiene unos 28.000 habitantes y se extiende sobre 76 km². Es conocido por sus playas de arena negra y la proximidad a spots de surf. En Punaauia se encuentran varios hoteles de lujo y el Museo de Tahití y las Islas. La carretera costera a lo largo de la bahía de Punaauia ofrece vistas espectaculares de la isla de Moorea. El municipio crece rápidamente debido a la migración desde Papeete. La economía se basa en el turismo y los servicios.",
      pt: "Punaauia situa-se na costa oeste do Taiti, a sul de Papeete, e é um local residencial e turístico popular. O município tem cerca de 28.000 habitantes e estende-se por 76 km². É conhecido pelas suas praias de areia preta e pela proximidade de locais de surf. Em Punaauia encontram-se vários hotéis de luxo e o Museu do Taiti e das Ilhas. A estrada costeira ao longo da baía de Punaauia oferece vistas espetaculares da ilha de Moorea. O município cresce rapidamente devido à migração de Papeete. A economia baseia-se no turismo e nos serviços.",
      fr: "Punaauia est située sur la côte ouest de Tahiti, au sud de Papeete, et constitue un lieu de résidence et de villégiature très prisé. La commune compte environ 28 000 habitants et s'étend sur 76 km². Elle est renommée pour ses plages de sable noir et sa proximité avec des spots de surf. Punaauia abrite plusieurs hôtels de luxe ainsi que le Musée de Tahiti et des Îles. La route côtière longeant la baie de Punaauia offre des vues spectaculaires sur l'île de Moorea. La commune connaît une croissance rapide due à l'exode de Papeete. L'économie repose sur le tourisme et les services.",
    },
