      hu: ["A híres Hinano sörfőzde székhelye", "Itt található V. Pomare király sírja", "James Norman Hall író korábbi lakhelye", "Fontos katonai bázisnak ad otthont"],
      ro: ["Sediul celebrei berării Hinano", "Conține mormântul regelui Pomare al V-lea", "Fosta reședință a scriitorului James Norman Hall", "Găzduiește o bază militară importantă"],
