    imageHint: "Tomb of King Pomare V in Arue",
    descriptionAdvanced: {
      de: "Arue ist eine vielseitige Gemeinde an der Nordostküste von Tahiti, die eine faszinierende Brücke zwischen wirtschaftlicher Moderne und historischem Erbe schlägt. Bekannt ist der Ort vor allem als Standort der Brasserie de Tahiti, in der das berühmte Hinano-Bier gebraut wird – ein Symbol der polynesischen Lebensart. Geschichtlich Interessierte finden hier das Grab von König Pomare V., dem letzten Herrscher des Königreichs Tahiti, dessen imposantes Denkmal aus Korallensteinen errichtet wurde. Ein weiteres kulturelles Highlight ist das Maison James Norman Hall, das ehemalige Wohnhaus des Mitautors von 'Meuterei auf der Bounty', das heute als Museum dient und Einblicke in das Leben des Schriftstellers bietet. Arue zeichnet sich zudem durch exklusive Wohnviertel an den Hängen und eine bedeutende militärische Präsenz aus. Die Lage am Meer bietet zudem Zugang zum Yachtclub von Tahiti, was die Gemeinde zu einem Zentrum für Segelsportler macht. Diese Mischung aus Industrie, königlicher Geschichte und literarischem Flair verleiht Arue einen ganz eigenen Charakter innerhalb des Ballungsraums von Papeete.",
      hu: "Arue egy különleges község Tahiti északkeleti partján, ahol a modern ipar, a királyi történelem és az irodalmi örökség fonódik össze. Itt található Polinézia egyik legismertebb márkájának, a Hinano sörnek a gyára, amely a helyi gazdaság egyik tartóoszlopa. A történelmi emlékek iránt érdeklődők számára Arue kötelező megálló, hiszen itt nyugszik V. Pomare, Tahiti utolsó királya; síremléke különleges koralltömbökből épült. A kultúra kedvelői ellátogathatnak James Norman Hall, a 'Lázadás a Bountyn' társszerzőjének egykori otthonába, amely ma múzeumként működik, megőrizve az író személyes tárgyait és könyvtárát. Arue nemcsak ipari és kulturális központ, hanem elegáns lakónegyed is, ahol a domboldalakról pazar kilátás nyílik az óceánra. A község ad otthont a Tahiti Yacht Clubnak is, így a vitorlázás szerelmesei számára is fontos bázis. A katonai jelenlét és a tengerparti sétányok dinamikus, mégis hagyományőrző légkört kölcsönöznek a településnek, amely szervesen kapcsolódik a fővároshoz, Papeetéhez.",
      ro: "Arue este o comună dinamică situată pe coasta de nord-est a insulei Tahiti, reprezentând un punct de întâlnire între tradiția regală și industria modernă. Localitatea este celebră la nivel internațional pentru că găzduiește sediul Brasserie de Tahiti, unde se produce berea Hinano, un simbol cultural al Polineziei Franceze. Din punct de vedere istoric, Arue are o importanță majoră deoarece aici se află mormântul regelui Pomare al V-lea, ultimul monarh al Tahitiului, un monument impunător construit din blocuri de corali. Iubitorii de literatură pot vizita casa memorială a lui James Norman Hall, coautor al celebrului roman 'Revolta de pe Bounty', transformată într-un muzeu ce păstrează atmosfera anilor '30. Comuna se mândrește, de asemenea, cu zone rezidențiale de lux situate pe dealurile din apropiere, oferind panorame superbe asupra oceanului, și găzduiește o importantă bază militară. Prezența Yacht Clubului Tahiti face din Arue un centru important pentru navigație și sporturi nautice, completând profilul unei comunități care reușește să își păstreze moștenirea istorică într-un context modern.",
      en: "Arue is a multifaceted commune located on the northeastern coast of Tahiti, offering a unique blend of industrial prowess, royal history, and literary heritage. It is widely recognized as the home of the Brasserie de Tahiti, where the iconic Hinano beer is produced, marking it as a significant economic hub for the archipelago. For history enthusiasts, Arue is the final resting place of King Pomare V, the last monarch of Tahiti; his tomb, constructed from coral stones, stands as a poignant reminder of the island's royal past. Cultural seekers can explore the James Norman Hall Home and Museum, the former residence of the co-author of 'Mutiny on the Bounty,' which offers a glimpse into the life of the famed American writer in the Pacific. The area is also known for its upscale residential districts and a notable military base, contributing to its diverse social fabric. With its scenic coastline hosting the Tahiti Yacht Club, Arue serves as a vital center for sailing and maritime activities, making it a key destination for those exploring the outskirts of the capital, Papeete.",
      es: "Arue se encuentra en la costa norte de Tahití, al este de Mahina, con 9.000 habitantes en 21 km². La costa destaca por acantilados rocosos y pequeñas playas. Arue alberga el Hotel InterContinental Tahiti Resort & Spa. Tiene importancia histórica por su puerto, usado antiguamente por balleneros. La economía está dominada por el turismo y el lugar tiene un ambiente suburbano tranquilo. El Monte Fareura ofrece rutas de senderismo.",
      pt: "Arue situa-se na costa norte de Tahiti, a leste de Mahina, com 9.000 habitantes em 21 km². A costa é marcada por falésias rochosas e pequenas praias. Arue abriga o hotel InterContinental Tahiti Resort & Spa. Tem importância histórica devido ao porto, antigamente usado por baleeiros. A economia é dominada pelo turismo e o local tem uma atmosfera suburbana tranquila. O Monte Fareura oferece trilhos para caminhadas.",
      fr: "Arue est une commune située sur la côte nord de Tahiti, à l'est de Mahina, comptant 9 000 habitants sur 21 km². La côte est marquée par des falaises rocheuses et de petites plages. Arue abrite l'hôtel InterContinental Tahiti Resort & Spa. La commune a une importance historique grâce au port d'Arue, autrefois utilisé par les baleiniers. L'économie est dominée par le tourisme. L'endroit possède une atmosphère suburbaine calme. Le mont Fareura offre des sentiers de randonnée.",
    },
