    facts: {
      de: ["Sitz des Rathauses von Moorea-Maiao", "Bekannt für zwei beeindruckende Wasserfälle", "Standort der ersten Druckerei in Polynesien", "Wichtiger Hafen für Fischerboote"],
      hu: ["Moorea-Maiao városházájának székhelye", "Két lenyűgöző vízeséséről ismert", "Polinézia első nyomdájának helyszíne", "Halászhajók fontos kikötője"],
      ro: ["Sediul primăriei Moorea-Maiao", "Cunoscută pentru două cascade impresionante", "Locația primei tipografii din Polinezia", "Port important pentru ambarcațiunile de pescuit"],
      en: ["Seat of the Moorea-Maiao town hall", "Known for two impressive waterfalls", "Site of the first printing press in Polynesia", "Important harbor for fishing boats"],
      es: ["Sede del ayuntamiento de Moorea-Maiao", "Conocido por dos impresionantes cascadas", "Ubicación de la primera imprenta en Polinesia", "Puerto importante para barcos de pesca"],
      pt: ["Sede da câmara municipal de Moorea-Maiao", "Conhecido por duas cascatas impressionantes", "Localização da primeira tipografia na Polinésia", "Porto importante para barcos de pesca"],
      fr: ["Siège de la mairie de Moorea-Maiao", "Connu pour ses deux cascades impressionnantes", "Site de la première imprimerie de Polynésie", "Port important pour les bateaux de pêche"],
    },
    imageHint: "Afareaitu waterfall in the lush mountains of Moorea",
    descriptionAdvanced: {
      de: "Afareaitu ist das administrative Zentrum der Insel Moorea und liegt eingebettet in eine beeindruckende Kulisse aus grünen Bergen an der Ostküste. Das Dorf ist geschichtlich von großer Bedeutung, da hier 1817 von der London Missionary Society die erste Druckerei Polynesiens errichtet wurde, in der die ersten Bücher in tahitianischer Sprache gedruckt wurden. Besucher werden oft von den beiden spektakulären Wasserfällen in der Nähe angezogen, die nach kurzen Wanderungen durch üppiges Farmland und Tropenwälder erreichbar sind. Der Ort selbst strahlt eine ruhige, authentische Atmosphäre aus, weit entfernt von den großen Hotelanlagen im Norden. Am kleinen Hafen liegen oft Fischerboote, und das Rathaus (Mairie) von Moorea-Maiao ist ein markantes Gebäude im Zentrum. Afareaitu ist auch ein wichtiger Ort für die lokale Kultur, mit alten Marae-Stätten in der Umgebung, die auf die polynesische Besiedlungsgeschichte hinweisen. Es ist der ideale Ort, um das tägliche Leben der Inselbewohner in einer malerischen Umgebung zwischen Lagune und Gipfeln zu erleben.",
      hu: "Afareaitu Moorea szigetének közigazgatási központja, amely a sziget keleti partján, meredek zöld hegycsúcsok tövében fekszik. A település történelmi jelentősége kiemelkedő: 1817-ben itt állították fel Francia Polinézia első nyomdáját a Londoni Missziós Társaság tagjai, ahol az első tahiti nyelvű Bibliákat és tankönyveket nyomtatták. A falu természeti vonzerejét a közeli Afareaitu-vízesések adják, amelyek két hatalmas vízoszlopként zúdulnak alá a bazaltsziklákról, és egy rövid, trópusi növényekkel teli túrával érhetők el. Afareaitu kikötője a helyi halászok fontos bázisa, a part mentén pedig Moorea-Maiao városházájának elegáns épülete látható. A település környékén számos ősi polinéz szentély (marae) maradványa található, ami jelzi a terület régmúltra visszanyúló spirituális szerepét. Ez a falu tökéletes választás azoknak, akik Moorea csendesebb, hagyományőrző oldalát szeretnék megismerni, távol a turisták által elárasztott északi üdülőövezetektől.",
      ro: "Afareaitu este centrul administrativ al insulei Moorea, fiind situat într-un decor natural dramatic, cu muntele Mou'aputa ridicându-se impunător deasupra sa. Satul deține un loc special în istoria Polineziei Franceze, deoarece aici a fost instalată prima tiparniță din regiune în anul 1817, de către misionarii englezi, marcând începutul alfabetizării în limba tahitiană. Principala atracție turistică este reprezentată de cele două cascade impresionante, accesibile prin poteci ce șerpuiesc printre plantații de ananas și ferigi arborescente. Spre deosebire de zonele turistice aglomerate din nordul insulei, Afareaitu păstrează o atmosferă locală autentică, fiind locul unde se află primăria și principalele instituții publice. Portul său este mereu activ, servind ambarcațiunile de pescuit ale comunității. În apropiere se pot vizita vestigii arheologice importante, precum vechile platforme ceremoniale 'marae', care atestă vechimea așezării. Afareaitu oferă o fereastră spre modul de viață tradițional polinezian, într-un peisaj unde muntele se întâlnește armonios cu laguna cristalină.",
      en: "Afareaitu serves as the administrative capital of Moorea, nestled on the island's scenic eastern coast beneath the towering emerald peaks of Mount Mou'aputa. The village is steeped in historical significance; in 1817, the London Missionary Society established French Polynesia's first printing press here, producing the first books in the Tahitian language. Beyond its history, Afareaitu is famed for its two majestic waterfalls, which are reachable via a moderate hike through lush tropical landscapes and local fruit plantations. The village center is home to the elegant town hall of Moorea-Maiao and serves as the primary hub for the island's essential services. Unlike the resort-heavy northern districts, Afareaitu offers a glimpse into everyday Polynesian life, with its quiet harbor and traditional family homes. The surrounding area also contains several ancient 'marae' (stone temples), highlighting the deep spiritual and cultural roots of the Tahitian people. It is a place where history, culture, and nature converge in a serene coastal setting.",
      es: "Afareaitu es la localidad principal de la isla de Moorea en la Polinesia Francesa, con unos 3.000 habitantes en 14 km². El municipio está situado en la costa norte y es conocido por sus playas de arena blanca y aguas cristalinas. El puerto de Afareaitu sirve como terminal de ferris. La economía está dominada por el turismo y la agricultura. En los alrededores hay plantaciones de piñas. La bahía de Opunohu se encuentra cerca. Afareaitu cuenta con un mercado tradicional polinesio. El lugar es un punto de partida para excursiones al interior de la isla.",
      pt: "Afareaitu é a principal localidade da ilha de Moorea, na Polinésia Francesa, com cerca de 3.000 habitantes em 14 km². O município situa-se na costa norte e é conhecido pelas suas praias de areia branca e águas cristalinas. O porto de Afareaitu serve como terminal de ferries. A economia é dominada pelo turismo e pela agricultura. Nos arredores existem plantações de ananás. A baía de Opunohu fica próxima. Afareaitu tem um mercado tradicional polinésio. O local é um ponto de partida para caminhadas no interior da ilha.",
      fr: "Afareaitu est le chef-lieu de l'île de Moorea en Polynésie française, comptant environ 3 000 habitants sur 14 km². La commune est située sur la côte nord et est réputée pour ses plages de sable blanc et ses eaux cristallines. Le port d'Afareaitu sert de terminal de ferry. L'économie est portée par le tourisme et l'agriculture. On trouve des plantations d'ananas dans les environs. La baie d'Opunohu est à proximité. Afareaitu possède une halle de marché traditionnelle polynésienne. Le village est un point de départ pour des randonnées vers l'intérieur de l'île.",
    },
