    imageHint: "Vaitape town harbor with Mount Otemanu background",
    descriptionAdvanced: {
      de: "Vaitape ist das pulsierende Herz von Bora Bora und der Ort, an dem das administrative und wirtschaftliche Leben der Insel zusammenläuft. Die Stadt liegt am Fuße der monumentalen Basaltblöcke der Berge Pahia und Otemanu, direkt am Ufer der tiefblauen Lagune. Hier befindet sich der Haupthafen, der die Insel mit dem Flughafen und den Resorts auf den umliegenden Motus verbindet. Die Hauptstraße der Stadt ist bekannt für ihre exklusiven Boutiquen, in denen die weltberühmten polynesischen schwarzen Perlen und lokales Kunsthandwerk angeboten werden. Auch historisch ist Vaitape von Bedeutung: Während des Zweiten Weltkriegs unterhielten die USA hier eine Militärbasis, deren Überreste in Form von alten Kanonen noch heute in der Umgebung zu finden sind. Jedes Jahr im Juli ist die Stadt Schauplatz des Heiva-Festivals, bei dem die Einheimischen ihr kulturelles Erbe mit Tanz und Gesang feiern.",
      hu: "Vaitape Bora Bora lüktető szíve, ahol a sziget adminisztratív és gazdasági élete zajlik. A település a Mount Pahia és a Mount Otemanu monumentális bazalttömbjeinek lábánál terül el, közvetlenül a mélykék lagúna partján. Itt található a fő kikötő, amely összeköti a szigetet a repülőtérrel és a környező motukon lévő üdülőhelyekkel. A város főutcája híres az exkluzív butikokról, ahol a világhírű polinéz fekete gyöngyöket és helyi kézműves termékeket kínálnak. Történelmi szempontból is jelentős helyszín, hiszen a második világháború alatt amerikai katonai bázis működött a közelben, aminek emlékeit a környéken található rozsdásodó ágyúk őrzik. Évente júliusban itt rendezik meg a Heiva fesztivált, ahol a helyiek hagyományos tánccal és énekkel ünneplik polinéz örökségüket, bemutatva a látogatóknak az autentikus szigetvilági kultúrát.",
      ro: "Vaitape este inima pulsândă a insulei Bora Bora și locul unde converge viața administrativă și comercială a arhipelagului. Orașul este situat la poalele monumentale ale munților Pahia și Otemanu, chiar pe malul lagunei de un albastru profund. Aici se află portul principal, care asigură legătura vitală între aeroport și complexele hoteliere situate pe „motu-urile” învecinate. Strada principală a orașului este faimoasă pentru buticurile sale exclusiviste, unde se comercializează perlele negre polineziene, recunoscute mondial, și produse de artizanat local. Din punct de vedere istoric, Vaitape păstrează amintirea prezenței militare americane din timpul celui de-al Doilea Război Mondial, tunurile ruginite fiind încă vizibile în împrejurimi. În fiecare an, în iulie, orașul găzduiește festivalul Heiva, o celebrare vibrantă a culturii polineziene prin dansuri tradiționale și competiții sportive.",
      en: "Vaitape is the vibrant heart of Bora Bora, serving as the central hub for the island's commercial, administrative, and social life. Nestled at the base of the majestic basalt peaks of Mount Pahia and Mount Otemanu, the town sits directly on the edge of the world-famous turquoise lagoon. It is home to the main harbor, where ferries transport visitors from the airport and connect the local community with the luxury resorts on the surrounding motus. The main street is lined with specialized boutiques offering the renowned Tahitian black pearls and authentic Polynesian crafts. Historically, the area served as a strategic military outpost for US forces during WWII, and remnants like coastal cannons can still be found nearby. Each July, Vaitape transforms into a stage for the Heiva festival, a grand celebration of Polynesian identity through traditional dance, music, and sports.",
      es: "Vaitape es la localidad principal de la isla de Bora Bora en la Polinesia Francesa, con unos 5.000 habitantes en 15 km². La ciudad está en la costa oeste y es el centro económico de la isla. El puerto recibe barcos de crucero. Vaitape tiene un aeropuerto a 4 km de distancia. La economía está dominada por el turismo de lujo, con numerosos bungalows sobre el agua. La laguna es famosa por su biodiversidad. El monte Otemanu domina la ciudad. Vaitape ofrece artesanía local y granjas de perlas.",
      pt: "Vaitape é a principal localidade da ilha de Bora Bora, na Polinésia Francesa, com cerca de 5.000 habitantes em 15 km². A cidade situa-se na costa oeste e é o centro económico da ilha. O porto é visitado por navios de cruzeiro. Vaitape possui um aeroporto a 4 km de distância. A economia é dominada pelo turismo de luxo, com inúmeros bangalôs sobre a água. A lagoa é famosa pela sua biodiversidade. O Monte Otemanu domina a cidade. Vaitape oferece artesanato local e quintas de pérolas.",
      fr: "Vaitape est le chef-lieu de l'île de Bora Bora en Polynésie française, avec environ 5 000 habitants sur 15 km². La ville est située sur la côte ouest et constitue le centre économique de l'île. Le port est desservi par des bateaux de croisière. Vaitape possède un aéroport situé à 4 km. L'économie est dominée par le tourisme de luxe, avec de nombreux bungalows sur pilotis. Le lagon est célèbre pour sa biodiversité. Le mont Otemanu surplombe la ville. Vaitape propose de l'artisanat local et des fermes perlières.",
    },
