    imageHint: "Uturoa town and harbor from Mount Tapioi",
    descriptionAdvanced: {
      de: "Uturoa liegt an der Nordküste der Insel Raiatea und fungiert als das wichtigste Verwaltungs- und Handelszentrum der Gesellschaftsinseln unter dem Winde. Als zweitgrößte Stadt Französisch-Polynesiens nach Papeete bietet Uturoa eine gut ausgebaute Infrastruktur mit Geschäften, einem lebhaften Markt und wichtigen Dienstleistungsstellen für Segler. Der Hafen der Stadt ist ein zentraler Anlaufpunkt für Yachten und Charterboote, die die Lagunen von Raiatea und der benachbarten Insel Taha'a erkunden. Überragt wird der Ort vom 294 Meter hohen Berg Tapioi, dessen Gipfel über einen Wanderweg erreichbar ist und einen weiten Blick über die Lagune bis hin nach Bora Bora ermöglicht. Uturoa ist bekannt für seine koloniale Architektur und die entspannte Atmosphäre, die typisch für das Leben auf den pazifischen Inseln ist. Neben der Funktion als Versorgungszentrum ist die Stadt ein idealer Ausgangspunkt für Ausflüge zu den kulturellen Stätten der Insel, insbesondere zum nahegelegenen Marae Taputapuatea, das zum UNESCO-Welterbe gehört.",
      hu: "Uturoa Raiatea szigetének északi részén található, és a Szélcsendes-szigetek legfontosabb közigazgatási és kereskedelmi központjaként szolgál. Papeete után ez Francia Polinézia második legnépesebb települése, ahol modern kikötő, üzletek és egy hangulatos helyi piac várja a látogatókat. A város élete szorosan összefügg a vitorlázással, hiszen jachtkikötője a térség egyik legfontosabb ellátóhelye a Csendes-óceánt átszelő hajósok számára. Uturoa közvetlenül a 294 méter magas Tapioi-hegy lábánál fekszik; a hegycsúcsra vezető túraútvonalról lenyűgöző panoráma nyílik a környező lagúnákra, tiszta időben pedig a szomszédos Bora Bora és Taha'a szigetei is látszanak. A város építészete a koloniális múlt jegyeit hordozza, utcái pedig betekintést engednek a polinéz mindennapokba. Kiváló kiindulópont a Raiatea szigetén található történelmi emlékek, köztük az UNESCO világörökség részét képező Taputapuatea marae felfedezéséhez.",
      ro: "Uturoa este situat pe coasta de nord a insulei Raiatea și servește drept principal centru administrativ și comercial al Insulelor Societății sub Vânt. Fiind al doilea oraș ca mărime din Polinezia Franceză după Papeete, Uturoa oferă o infrastructură solidă, incluzând bănci, magazine și o piață locală vibrantă unde se vând produse artizanale și fructe exotice. Portul său este un punct de referință pentru comunitatea internațională de iahting, fiind un centru vital de aprovizionare pentru cei care navighează prin arhipelag. Orașul se află la baza muntelui Tapioi, care atinge o înălțime de 294 de metri; o drumeție până în vârf oferă o vedere panoramică asupra lagunelor turcoaz și a insulelor vecine, precum Taha'a și Bora Bora. Atmosfera din Uturoa îmbină farmecul colonial cu dinamismul unui nod de transport maritim. Pe lângă rolul său logistic, orașul facilitează accesul către siturile culturale majore ale insulei, Raiatea fiind considerată centrul spiritual al vechii Polinezii.",
      en: "Uturoa, situated on the northern tip of Raiatea, stands as the commercial and administrative heart of the Leeward Islands. As French Polynesia’s second most important urban center after Papeete, it serves as a critical hub for regional trade and maritime logistics. The town is famous for its sheltered harbor, which attracts sailors from across the globe and acts as a primary base for yacht charters exploring the shared lagoon of Raiatea and Taha'a. Dominating the skyline is Mount Tapioi, a 294-meter peak that provides a popular hiking trail leading to vistas of the surrounding coral reefs and the distant silhouette of Bora Bora. The town center features a mix of traditional Polynesian markets and colonial-style buildings, offering a glimpse into the local way of life. Beyond its role as a supply station, Uturoa is a gateway to the sacred history of Raiatea, often referred to as the 'cradle of Polynesian culture,' with the ancient Marae Taputapuatea located just a short drive away.",
      es: "Uturoa es la localidad principal de la isla de Raiatea en la Polinesia Francesa, con unos 4.000 habitantes en 16 km². La ciudad cuenta con un puerto importante y un aeropuerto (RFP). Uturoa es el centro administrativo de las Islas de Sotavento. La economía se basa en la agricultura, la pesca y el turismo. En los alrededores hay plantaciones de vainilla. El mercado de Uturoa ofrece productos locales. La bahía de Faaroa está cerca. Uturoa tiene un bonito paseo marítimo. La isla alberga el histórico Marae Taputapuatea.",
      pt: "Uturoa é a localidade principal da ilha de Raiatea, na Polinésia Francesa, com cerca de 4.000 habitantes em 16 km². A cidade tem um porto importante e um aeroporto (RFP). Uturoa é o centro administrativo das Ilhas de Sotavento. A economia baseia-se na agricultura, na pesca e no turismo. Existem plantações de baunilha nas proximidades. O mercado de Uturoa oferece produtos locais. A baía de Faaroa fica perto. Uturoa tem uma bela marginal. A ilha alberga o histórico Marae Taputapuatea.",
      fr: "Uturoa est le chef-lieu de l'île de Raiatea en Polynésie française, comptant environ 4 000 habitants sur 16 km². La ville possède un port important et un aéroport (RFP). Uturoa est le centre administratif des îles Sous-le-Vent. L'économie repose sur l'agriculture, la pêche et le tourisme. On trouve des plantations de vanille dans les environs. Le marché d'Uturoa propose des produits locaux. La baie de Faaroa est à proximité. Uturoa dispose d'un joli front de mer. L'île abrite le site historique Marae Taputapuatea.",
    },
