      hu: ["lakosság: 2 500", "terület: 30 km²", "repülőtér: NHV", "kopra termelés: 50 tonna/év", "székesegyház: 1977-ben épült", "vízesések száma: 3"],
      ro: ["populație: 2.500 (2017)", "suprafață: 30 km²", "aeroport: Nuku Hiva (NHV)", "producție copra: 50 tone/an", "catedrală: construită în 1977", "număr cascade: 3"],
      en: ["population: 2,500 (2017)", "area: 30 km²", "airport code: NHV", "copra production: 50 tons/year", "cathedral built: 1977", "waterfalls: 3"],
      es: ["Habitantes: 2.500 (2017)", "Superficie: 30 km²", "Aeropuerto: Nuku Hiva (NHV)", "Producción de copra: 50 toneladas/año", "Catedral de San Pedro y San Pablo: construida en 1977", "Número de cascadas en los alrededores: 3"],
      pt: ["Habitantes: 2.500 (2017)", "Área: 30 km²", "Aeroporto: Nuku Hiva (NHV)", "Produção de copra: 50 toneladas/ano", "Catedral de São Pedro e São Paulo: construída em 1977", "Número de cascatas nos arredores: 3"],
      fr: ["Habitants : 2 500 (2017)", "Superficie : 30 km²", "Aéroport : Nuku Hiva (NHV)", "Production de coprah : 50 tonnes/an", "Cathédrale Saint-Pierre-et-Saint-Paul : édifiée en 1977", "Nombre de cascades dans les environs : 3"],
