      en: ["population: 2,000 (2017)", "area: 25 km²", "airport code: HIX", "Gauguin's grave: since 1903", "copra production: 30 tons/year", "tiki statues: 5"],
      pt: ["População: 2.000 (2017)", "Área: 25 km²", "Aeroporto: Hiva Oa (HIX)", "Túmulo de Gauguin: desde 1903", "Produção de copra: 30 toneladas/ano", "Número de estátuas tiki na zona: 5"],
      fr: ["Population : 2 000 (2017)", "Superficie : 25 km²", "Aéroport : Hiva Oa (HIX)", "Tombe de Gauguin : depuis 1903", "Production de coprah : 30 tonnes/an", "Nombre de statues tiki dans les environs : 5"],
      es: ["Población: 2.000 (2017)", "Superficie: 25 km²", "Aeropuerto: Hiva Oa (HIX)", "Tumba de Gauguin: desde 1903", "Producción de copra: 30 toneladas/año", "Número de estatuas tiki en la zona: 5"],
