      pt: ["População: aprox. 500 (2017)", "Área da ilha Mangareva: 15,4 km²", "Ano de construção da catedral St. Michel: 1839", "Ponto mais alto de Mangareva: Mont Duff, 441 m", "Distância ao Taiti: aprox. 1.650 km", "Número de igrejas católicas em Rikitea: 2"],
      fr: ["Nombre d'habitants : env. 500 (2017)", "Superficie de l'île Mangareva : 15,4 km²", "Année de construction de la cathédrale Saint-Michel : 1839", "Point culminant de Mangareva : Mont Duff, 441 m", "Distance de Tahiti : env. 1 650 km", "Nombre d'églises catholiques à Rikitea : 2"],
