    imageHint: "Avatoru pass and village Rangiroa aerial",
    descriptionAdvanced: {
      de: "Avatoru ist das pulsierende Herz des Rangiroa-Atolls und dient als administratives sowie wirtschaftliches Zentrum der Region. Das Dorf erstreckt sich entlang des gleichnamigen Passes, einer der zwei Hauptöffnungen, durch die das Meerwasser in die riesige Lagune strömt. Besucher finden hier eine authentische polinéische Atmosphäre mit kleinen Pensionen, lokalen Kunsthandwerksläden und einer markanten katholischen Kirche. Besonders bedeutend ist die Perlenzucht; die nahegelegene Farm Gauguin’s Pearl bietet detaillierte Einblicke in die Kultivierung der berühmten schwarzen Tahiti-Perlen. Für Taucher ist Avatoru der ideale Ausgangspunkt, um die starken Strömungen des Passes zu erleben, wo man häufig auf Silberspitzenhaie, große Hammerhaie und riesige Schulen von Blaustreifen-Schnappern trifft. Die Hauptstraße des Dorfes lädt zu gemütlichen Radtouren unter Kokospalmen ein, weit weg vom Massentourismus der größeren Inselgruppen.",
      hu: "Avatoru a Rangiroa-atoll két fő átjárójának egyike mellett fekszik, és a szigetcsoport adminisztratív, valamint kereskedelmi központjaként szolgál. A település hangulata békés, ahol a helyiek élete szorosan összefonódik az óceán ritmusával. Itt található a Gauguin’s Pearl farm, amely betekintést nyújt a világhírű polinéz fekete gyöngyök termesztésének aprólékos folyamatába. A falu kikötője a búvárok és sznorkelezők kiindulópontja, akik az Avatoru-átjáró áramlataiban szürke szirticápákkal és hatalmas manta rájákkal találkozhatnak. A településen kis panziók, kézműves boltok és egy díszes katolikus templom is helyet kapott, miközben a pálmafákkal szegélyezett utak mentén a látogatók megtapasztalhatják az igazi polinéz vendégszeretetet és az atoll-életmód nyugalmát. A falu kerékpárral is könnyen bejárható, lehetőséget adva a lagúna és az óceán közötti keskeny földnyelv felfedezésére.",
      ro: "Avatoru este centrul administrativ și comercial al atolului Rangiroa, fiind situat la extremitatea vestică a pasului cu același nume. Satul oferă o incursiune autentică în viața polineziană, cu străzi mărginite de palmieri și case colorate. Este un punct de referință pentru industria perlelor negre, găzduind ferme renumite precum Gauguin’s Pearl, unde vizitatorii pot învăța despre procesul delicat de grefare a scoicilor. Pentru pasionații de scufundări, Avatoru este poarta de acces către o lume subacvatică spectaculoasă; curenții din pasul Avatoru atrag rechini cu vârfuri argintii, rechini ciocan și bancuri imense de pești tropicali. Localitatea dispune de mici unități de cazare tip pensiune, magazine de suveniruri și o biserică catolică pitorească. Atmosfera este una relaxată, fiind locul ideal pentru a explora atolul cu bicicleta sau pentru a urmări apusul peste apele nesfârșite ale Pacificului, departe de agitația marilor centre turistice.",
      en: "Avatoru serves as the administrative and economic hub of the Rangiroa atoll, situated at the western end of the Avatoru Pass. The village offers a glimpse into authentic Tuamotu life, where the rhythm of the day is dictated by the tides and the arrivals at the local pier. It is a major center for the Tahitian black pearl industry, with the Gauguin’s Pearl farm providing educational tours on the intricate process of pearl cultivation. The nearby pass is a world-renowned diving site, famous for its drift dives where encounters with silvertip sharks, manta rays, and large schools of jackfish are common. Within the village, visitors can find small grocery stores, a post office, and charming guesthouses. Cycling along the main road that connects the lagoon side to the ocean side is a popular way to explore, allowing travelers to soak in the tranquil environment and the hospitality of the local community.",
      es: "Avatoru es un asentamiento en Rangiroa, el atolón más grande de la Polinesia Francesa. Situado en la costa norte, es conocido por su puerto de perlas y su mundo submarino. Posee uno de los pocos pasos (Tiputa) en el arrecife, lo que atrae una rica fauna marina. La economía se basa en el cultivo de perlas negras, el turismo de buceo y el procesamiento de coco. La población de unos 1.500 habitantes está conectada con Tiputa por carretera.",
      pt: "Avatoru é um assentamento em Rangiroa, o maior atolão da Polinésia Francesa. Situado na costa norte, é conhecido pelo seu porto de pérolas e pelo mundo submarino único. Possui uma das poucas passagens (Tiputa) no recife, o que atrai uma fauna marinha rica. A economia baseia-se no cultivo de pérolas negras, no turismo de mergulho e no processamento de coco. A população de cerca de 1.500 habitantes está ligada a Tiputa por estrada.",
      fr: "Avatoru est un établissement sur l'île de Rangiroa, le plus grand atoll de Polynésie française. Le village est situé sur la côte nord de l'atoll et est connu pour son port perlier et son monde sous-marin unique. Avatoru dispose de l'une des rares passes (Tiputa) dans le récif, attirant une faune marine riche. L'économie repose sur la perliculture, le tourisme (plongée) et la transformation de la noix de coco. La population est d'environ 1 500 habitants.",
    },
