    imageHint: "Rotoava village street Fakarava",
    descriptionAdvanced: {
      de: "Rotoava ist das charmante Hauptdorf des Fakarava-Atolls in Französisch-Polynesien und dient als Tor zu einem der unberührtesten Ökosysteme der Welt. Da das gesamte Atoll von der UNESCO als Biosphärenreservat anerkannt ist, herrscht in Rotoava eine Atmosphäre von tiefem Respekt gegenüber der Natur. Das Dorf ist geprägt von korallengesäumten Wegen, farbenfrohen Gärten und einer entspannten Lebensweise. Eine der markantesten Sehenswürdigkeiten ist der alte Leuchtturm, der vollständig aus Korallenstein errichtet wurde, sowie die kleine katholische Kirche mit ihren kunstvollen Holzschnitzereien. Rotoava ist zudem der zentrale Knotenpunkt für Taucher, die den berühmten Nordpass von Fakarava erkunden möchten, der für seine unglaubliche Vielfalt an Haien und Korallen bekannt ist. Trotz der Anlegestelle für Kreuzfahrtschiffe hat das Dorf seinen authentischen polynesischen Charakter bewahrt. Hier können Besucher das tägliche Leben der Inselbewohner beobachten, die oft vom Fischfang und der Perlenzucht leben, während sie die endlose Weite des türkisfarbenen Ozeans genießen.",
      hu: "Rotoava a Fakarava-atoll központi települése Francia Polinéziában, és egyben a legfontosabb kiindulópont az UNESCO bioszféra-rezervátum felfedezéséhez. A falu különleges hangulatát a korallos talaj, a pálmafákkal övezett utak és az óceán közelsége határozza meg. Az itt élők büszkék kulturális örökségükre, amelynek egyik legszebb példája a fehérre meszelt, díszes katolikus templom és a korallkőből épült régi világítótorony. Rotoava fontos kikötőhely a Tuamotu-szigetvilágot bejáró hajók és luxusjachtok számára, emellett a búvárok paradicsoma is, hiszen innen érhető el az atoll északi átjárója, amely világhírű gazdag tengeri élővilágáról. A faluban sétálva megismerhetjük a polinéz vendégszeretetet, megkóstolhatjuk a helyi különlegességeket és betekintést nyerhetünk a feketeperle-tenyésztés rejtelmeibe is. Rotoava az a hely, ahol az idő lelassul, és a látogatók közvetlen közelről tapasztalhatják meg az érintetlen trópusi természet és a hagyományos szigetlakó életmód tökéletes harmóniáját.",
      ro: "Rotoava este principala așezare de pe atolul Fakarava din Polinezia Franceză, un loc unde tradiția insulară se întâlnește cu peisaje naturale protejate de UNESCO. Satul este situat în partea de nord-est a atolului și se remarcă prin simplitatea sa pitorească, având drumuri străjuite de flori tropicale și case construite în stil local. Un simbol important al comunității este biserica catolică albă, cu detalii decorative realizate din materiale marine, dar și farul istoric ridicat din blocuri de corali, o raritate arhitecturală în regiune. Rotoava servește ca hub central pentru turiștii care vin să exploreze biodiversitatea marină excepțională a atolului, în special pentru scufundări în celebrul pas de nord, unde pot fi observați rechini gri și corali rari. Deși primește vizitatori de pe nave de croazieră, satul își păstrează calmul specific polinezian, locuitorii fiind implicați activ în conservarea mediului înconjurător și în cultivarea perlelor negre, oferind astfel o experiență autentică și sustenabilă tuturor celor care îi trec pragul.",
      en: "Rotoava is the tranquil administrative and social heart of Fakarava atoll in French Polynesia. As part of a UNESCO Biosphere Reserve, the village is a model of environmental harmony, where life follows the gentle rhythms of the Pacific tides. The settlement is characterized by its long, coral-lined main road, flanked by vibrant gardens and coconut palms. Notable landmarks include the charming Jean de la Croix Catholic Church and a unique lighthouse constructed entirely from coral stones, reflecting the ingenuity of the local inhabitants. Rotoava is the primary base for world-class diving expeditions to Fakarava’s northern pass, renowned for its incredible density of marine life and spectacular coral formations. The village also boasts a safe anchorage for yachts and cruise ships, making it a vital link in the Tuamotu Archipelago's maritime network. Visitors can enjoy local hospitality, explore pearl farms, or simply witness the stunning turquoise waters of the lagoon, all while experiencing the authentic and unhurried lifestyle of a remote Polynesian community.",
      es: "Rotoava es el asentamiento principal del atolón de Fakarava, una Reserva de la Biosfera de la UNESCO en las islas Tuamotu. El lugar se encuentra en la costa noroeste del atolón y es conocido por su naturaleza virgen y su diversa fauna. La laguna es un área protegida con especies de aves raras y una rica fauna marina. La economía se apoya en el turismo, especialmente el buceo, la cría de perlas y el cultivo de copra. Rotoava tiene un pequeño puerto y un aeródromo con conexiones regulares a Tahití. La población es de unos 500 habitantes que viven en casas tradicionales. La carretera principal recorre la costa y conecta los pueblos dispersos del atolón.",
      pt: "Rotoava é o principal assentamento do atol de Fakarava, uma Reserva da Biosfera da UNESCO nas Ilhas Tuamotu. O local situa-se na costa noroeste do atol e é conhecido pela sua natureza virgem e vida selvagem diversificada. A lagoa é uma área protegida com espécies de aves raras e uma rica fauna marinha. A economia baseia-se no turismo, especialmente no mergulho, na criação de pérolas e no cultivo de copra. Rotoava tem um pequeno porto e um aeródromo com ligações regulares ao Taiti. A população é de cerca de 500 habitantes, que vivem em casas tradicionais. A estrada principal corre ao longo da costa e liga as aldeias dispersas do atol.",
      fr: "Rotoava est le chef-lieu de l'atoll de Fakarava, une réserve de biosphère de l'UNESCO située dans les îles Tuamotu. Le village se trouve sur la côte nord-ouest de l'atoll et est réputé pour sa nature préservée et sa faune diversifiée. Le lagon est une zone protégée abritant des espèces d'oiseaux rares et une riche faune marine. L'économie repose sur le tourisme, notamment la plongée sous-marine, la perliculture et la culture du coprah. Rotoava possède un petit port et un aérodrome avec des liaisons régulières vers Tahiti. La population est d'environ 500 habitants vivant dans des maisons traditionnelles. La route principale longe la côte et relie les villages dispersés de l'atoll.",
    },
