      es: ["Población: aprox. 500 (2017)", "Superficie de la isla de Rurutu: 36 km²", "Longitud de la cueva Ana Aeo: aprox. 50 m", "Año de construcción de la iglesia católica: 1876", "Elevación más alta: 389 m", "Distancia a Tahiti: 570 km"],
