      fr: ["Habitants : environ 500 (2017)", "Superficie de l'île de Ua Pou : 105 km²", "Altitude du mont Oave : 1 232 m", "Année de construction de l'église catholique : 1856", "Nombre de statues Tiki : 12", "Distance de Tahiti : 1 400 km"],
