    imageHint: "Patio village and lagoon Taha'a",
    descriptionAdvanced: {
      de: "Patio ist das beschauliche Verwaltungszentrum der Insel Taha'a, die innerhalb der Gesellschaftsinseln als „Vanille-Insel“ Weltruf genießt. Der Ort liegt an der geschützten Nordküste und ist der Sitz des Rathauses der Gemeinde Taha'a. Die Umgebung von Patio ist geprägt von üppigen Vanilleplantagen, auf denen die wertvollen Schoten in mühsamer Handarbeit bestäubt und getrocknet werden. Eine besondere kulturelle Bedeutung kommt dem Dorf als Austragungsort des jährlichen Steinfisch-Festivals zu, einer traditionellen Fangmethode, die nur noch an wenigen Orten in Polynesien praktiziert wird. Besucher schätzen Patio für seine authentische Atmosphäre, die fernab vom Massentourismus einen Einblick in das echte Inselleben bietet. Die lokale Wirtschaft wird durch den Export von Vanille und Kopra sowie durch den aufstrebenden Ökotourismus getragen, der die unberührte Natur der Lagune betont.",
      hu: "Patio Taha'a szigetének bájos közigazgatási központja, amely a Társaság-szigetek csoportjában a „Vanília-sziget” néven vált híressé. A település a sziget északi partján fekszik, és itt található Taha'a község városházája is. A környék gazdasági motorja a vaníliatermesztés; a környező lankákon sorakozó ültetvények biztosítják a világ egyik legjobb minőségű fűszerét. Patio kulturális szempontból is kiemelkedő, hiszen ez az évenkénti kőhalász-fesztivál egyik fő helyszíne, ahol a helyiek egy ősi, közösségi halászati módot elevenítenek fel. A falu autentikus polinéz hangulatot áraszt, távol a nagy üdülőhelyek zajától, lehetőséget adva a látogatóknak a helyi kézművesség és gasztronómia megismerésére. A kikötő fontos logisztikai pont, ahonnan a sziget terményeit szállítják a szomszédos Raiatea-ra vagy távolabbi piacokra.",
      ro: "Patio este centrul administrativ liniștit al insulei Taha'a, cunoscută în întreaga lume sub numele de „Insula Vaniliei”. Localitatea găzduiește sediul primăriei comunei Taha'a și este punctul central pentru coordonarea activităților economice de pe insulă. Zona înconjurătoare este dominată de plantații de vanilie, unde localnicii practică polenizarea manuală a orhideelor pentru a produce faimoasele păstăi aromate. Un eveniment cultural major care are loc aici este festivalul anual de pescuit cu pietre, o tradiție polineziană ancestrală care adună întreaga comunitate. Patio oferă o privire autentică asupra vieții insulare, fiind mult mai puțin comercială decât insulele vecine. Economia locală se bazează pe agricultură și pe micile afaceri de procesare a vaniliei, care atrag turiști interesați de gastronomie și cultură locală în acest cadru tropical spectaculos.",
      en: "Patio is the charming administrative heart of Taha'a, an island celebrated globally as the \"Vanilla Island\" within the Society Archipelago. Located on the island's northern coast, it serves as the seat of the Taha'a commune's town hall and government offices. The area surrounding Patio is famous for its lush vanilla plantations, where the prized beans are meticulously hand-pollinated and cured. Culturally, the village is a focal point for the annual stone-fishing festival, a traditional Polynesian practice where villagers beat the water with stones to drive fish into the shallows. Patio retains an authentic, unhurried atmosphere, offering visitors a genuine glimpse into French Polynesian island life away from the major tourist tracks. Its port is a vital link for the island's agricultural exports, including vanilla, copra, and pearls, connecting Taha'a to the global market.",
      es: "Patio es un asentamiento en la isla de Hiva Oa, que pertenece a las islas Marquesas. El lugar se encuentra en la costa norte y es conocido por su proximidad a los sitios arqueológicos de Puamau y las famosas estatuas Tiki. La economía se basa en la agricultura (copra, café) y el turismo. Patio cuenta con una iglesia del siglo XIX. La población es de unos 500 habitantes. La isla de Hiva Oa es conocida sobre todo como la última residencia del artista Paul Gauguin. El paisaje es montañoso con valles profundos. Patio ofrece un puerto para yates.",
      pt: "Patio é um assentamento na ilha de Hiva Oa, que pertence às Ilhas Marquesas. O local situa-se na costa norte e é conhecido pela sua proximidade aos sítios arqueológicos de Puamau e às famosas estátuas Tiki. A economia baseia-se na agricultura (copra, café) e no turismo. Patio possui uma igreja do século XIX. A população é de cerca de 500 habitantes. A ilha de Hiva Oa é conhecida sobretudo como a última residência do artista Paul Gauguin. A paisagem é montanhosa com vales profundos. Patio oferece um porto para iates.",
      fr: "Patio est une localité sur l'île de Hiva Oa, qui appartient aux îles Marquises. Le village est situé sur la côte nord et est réputé pour sa proximité avec les sites archéologiques de Puamau et les célèbres statues Tiki. L'économie repose sur l'agriculture (coprah, café) et le tourisme. Patio dispose d'une église datant du XIXe siècle. La population est d'environ 500 habitants. L'île d'Hiva Oa est surtout connue pour avoir été la dernière demeure de l'artiste Paul Gauguin. Le paysage est montagneux avec des vallées profondes. Patio propose un port pour les yachts.",
    },
