    facts: {
      de: ["Wohnort von Paul Gauguin von 1891 bis 1893", "Beherbergt den Botanischen Garten Harrison Smith", "Zentrum für den Anbau von Ingwer und exotischen Blumen", "Liegt nahe dem berühmten Vaihiria-See"],
      hu: ["Paul Gauguin lakhelye 1891 és 1893 között", "Itt található a Harrison Smith botanikus kert", "A gyömbér és egzotikus virágok termesztésének központja", "A híres Vaihiria-tó közelében fekszik"],
      ro: ["Reședința lui Paul Gauguin între 1891 și 1893", "Găzduiește Grădina Botanică Harrison Smith", "Centru pentru cultivarea ghimbirului și a florilor exotice", "Situat lângă celebrul lac Vaihiria"],
      en: ["Residence of Paul Gauguin from 1891 to 1893", "Home to the Harrison Smith Botanical Garden", "Center for ginger and exotic flower cultivation", "Located near the famous Lake Vaihiria"],
      es: ["Lugar de residencia de Paul Gauguin de 1891 a 1893", "Alberga el Jardín Botánico Harrison Smith", "Centro de cultivo de jengibre y flores exóticas", "Situado cerca del famoso lago Vaihiria"],
      pt: ["Local de residência de Paul Gauguin de 1891 a 1893", "Abriga o Jardim Botânico Harrison Smith", "Centro de cultivo de gengibre e flores exóticas", "Localizado perto do famoso lago Vaihiria"],
      fr: ["Lieu de résidence de Paul Gauguin de 1891 à 1893", "Abrite le jardin botanique Harrison Smith", "Centre de culture de gingembre et de fleurs exotiques", "Situé près du célèbre lac Vaihiria"],
    },
    imageHint: "Harrison Smith botanical garden Mataiea",
    descriptionAdvanced: {
      de: "Mataiea ist ein idyllisches Dorf an der Südküste von Tahiti, das für seine außergewöhnliche natürliche Schönheit und seine reiche kulturelle Geschichte bekannt ist. Der Ort erlangte weltweite Berühmtheit durch den französischen Maler Paul Gauguin, der hier zwischen 1891 und 1893 lebte und einige seiner bedeutendsten Werke schuf, inspiriert von der unberührten Landschaft und den Menschen. Ein weiteres Highlight in Mataiea ist der Harrison Smith Botanische Garten, der 1919 von dem amerikanischen Physiker und Botaniker gegründet wurde. Der Garten beherbergt eine beeindruckende Sammlung tropischer Pflanzen aus der ganzen Welt, darunter riesige Lotosblumen und seltene Orchideen. Geografisch zeichnet sich die Region durch ihre üppige Vegetation und die Nähe zum Vaihiria-See aus, dem einzigen Hochlandsee Tahitis, der für seine Legenden über „Aale mit Ohren“ bekannt ist. Die fruchtbaren Böden von Mataiea machen den Ort zu einem wichtigen Zentrum für den Anbau von Ingwer und exotischen Blumen, was dem Dorf eine besondere Atmosphäre und einen betörenden Duft verleiht.",
      hu: "Mataiea faluja Tahiti déli partvidékén fekszik, és a sziget egyik legtermékenyebb, legzöldebb területének számít. A település neve örökre összefonódott Paul Gauguin francia festőművész nevével, aki 1891 és 1893 között itt talált menedéket és ihletet. Gauguin ebben a faluban festette meg legikonikusabb műveit, amelyeken a polinéz életstílust és a trópusi táj vad szépségét örökítette meg. A természetkedvelők számára kötelező látnivaló a Harrison Smith botanikus kert, amelyet 1919-ben alapítottak. Ez a kert ma is otthont ad számos egzotikus növényfajnak, óriás tündérrózsáknak és ritka fafajtáknak, amelyeket a világ minden tájáról gyűjtöttek össze. A környék domborzata is különleges: Mataiea közelében található a Vaihiria-tó, Tahiti egyetlen hegyi tava, amelyhez számos helyi legenda és különös vízi lények története kapcsolódik. A falu gazdasága ma is a mezőgazdaságon alapul, különösen a gyömbér és a színpompás egzotikus virágok termesztése jelentős, amelyek illata belengi az egész környéket.",
      ro: "Mataiea este un sat pitoresc situat în partea de sud a insulei Tahiti, renumit pentru peisajele sale luxuriante și moștenirea culturală profundă. Localitatea a devenit celebră în întreaga lume datorită pictorului francez Paul Gauguin, care s-a stabilit aici între anii 1891 și 1893. În această perioadă de izolare creativă, Gauguin a realizat unele dintre cele mai importante capodopere ale sale, capturând esența vieții polineziene și culorile vibrante ale naturii locale. Un punct de atracție major în Mataiea este Grădina Botanică Harrison Smith, înființată în 1919 de un botanist american pasionat. Grădina se întinde pe o suprafață generoasă și adăpostește o colecție impresionantă de plante tropicale, inclusiv nufărul uriaș de Amazon și diverse specii de arbori exotici. De asemenea, satul este punctul de plecare către lacul Vaihiria, singurul lac de munte din Tahiti, înconjurat de legende locale despre creaturi mistice. Economia locală este susținută de cultivarea ghimbirului și a florilor exotice, transformând Mataiea într-un centru al biodiversității și al tradiției agricole taitiene.",
      en: "Mataiea is a lush village on the southern coast of Tahiti, often regarded as one of the most verdant and fertile districts of the island. It holds a special place in art history as the residence of the famous French post-impressionist painter Paul Gauguin from 1891 to 1893. During his time here, Gauguin produced some of his most legendary paintings, drawing inspiration from the serene lifestyle and the vivid colors of the tropical environment. Another major attraction is the Harrison Smith Botanical Garden, established in 1919 by an American physicist turned botanist. This expansive garden is home to a world-class collection of exotic flora, including giant water lilies and rare tropical hardwoods. The area is also geographically unique due to its proximity to Lake Vaihiria, Tahiti’s only highland lake, shrouded in local myths and accessible via scenic mountain trails. Today, Mataiea remains a vibrant center for the cultivation of ginger and exotic flowers, maintaining a peaceful atmosphere that continues to attract those seeking the authentic, natural beauty of southern Tahiti.",
      es: "Mataiea es una pequeña ciudad en la costa sur de Tahiti, la isla principal de la Polinesia Francesa. El lugar es famoso por sus playas de arena negra y su cercanía al río Vaiana. La economía se basa en la agricultura (piña, vainilla) y el turismo. Mataiea cuenta con varias iglesias históricas, incluida la iglesia católica de St. Michel del siglo XIX. La población es de unos 1.000 habitantes. La localidad sirve como zona residencial para trabajadores que se desplazan a la capital, Papeete. El entorno se caracteriza por plantaciones y colinas verdes.",
      pt: "Mataiea é uma pequena cidade na costa sul do Tahiti, a ilha principal da Polinésia Francesa. O local é conhecido pelas suas praias de areia negra e proximidade com o rio Vaiana. A economia baseia-se na agricultura (ananás, baunilha) e no turismo. Mataiea tem várias igrejas históricas, incluindo a igreja católica de St. Michel do século XIX. A população é de cerca de 1.000 habitantes. O local serve como área residencial para pessoas que trabalham na capital, Papeete. Os arredores são caracterizados por plantações e colinas verdes.",
      fr: "Mataiea est une petite ville sur la côte sud de Tahiti, l'île principale de la Polynésie française. Le lieu est connu pour ses plages de sable noir et sa proximité avec la rivière Vaiana. L'économie repose sur l'agriculture (ananas, vanille) et le tourisme. Mataiea possède plusieurs églises historiques, dont l'église catholique Saint-Michel datant du XIXe siècle. La population s'élève à environ 1 000 habitants. La localité sert de zone résidentielle pour les navetteurs travaillant dans la capitale, Papeete. Les environs sont marqués par des plantations et des collines verdoyantes.",
    },
