      hu: ["A Paul Gauguin Múzeum helyszíne", "Tahiti szigetének legősibb községe", "A 'Vaima' forrásparkról ismert", "A hagyományos kézművesség fontos helyszíne"],
      ro: ["Locația Muzeului Paul Gauguin", "Cea mai veche comună de pe insula Tahiti", "Cunoscută pentru parcul cu izvoare 'Vaima'", "Loc important pentru meșteșugurile tradiționale"],
      en: ["Site of the Paul Gauguin Museum", "Oldest commune on the island of Tahiti", "Known for the 'Vaima' spring park", "Important site for traditional crafts"],
