    imageHint: "Papenoo valley lush green mountains",
    descriptionAdvanced: {
      de: "Das Dorf Papenoo liegt an der Nordküste von Tahiti und ist vor allem als Tor zum gewaltigen Papenoo-Tal bekannt, dem größten Kraterbecken der Insel. Der gleichnamige Fluss ist der längste Tahitis und mündet hier in den Pazifik, was an der Flussmündung ideale Bedingungen für Surfer schafft, die die starken Strömungen und hohen Wellen schätzen. Das Hinterland von Papenoo ist ein Paradies für Naturliebhaber; es verbirgt zahlreiche archäologische Schätze wie Marae (heilige Kultstätten) und alte Siedlungsreste polynesischer Stämme. Im Tal befinden sich zudem wichtige Wasserkraftwerke, die einen Großteil der Energie für die Insel erzeugen. Die Landschaft ist geprägt von schroffen Bergen, tiefen Schluchten und einer fast unberührten Flora mit endemischen Pflanzenarten. Geführte Touren ins Tal bieten Einblicke in die Geologie und die reiche Mythologie der Region. Wer Tahiti abseits der klassischen Hotelstrände erleben möchte, findet in Papenoo den perfekten Ausgangspunkt für Expeditionen ins wilde Herz der Insel.",
      hu: "Papenoo települése Tahiti északi részén található, és a sziget \"zöld kapujaként\" funkcionál a látogatók számára. Itt kezdődik ugyanis a Papenoo-völgy, Tahiti legnagyobb és legmélyebb völgye, amely egy ősi vulkáni kráter maradványa. A falu a Papenoo-folyó torkolatánál fekszik; a folyó hordalékából képződött fekete homokos part és az erős hullámzás miatt a környék a szörfösök egyik kedvenc találkahelye. A völgy belseje felé haladva a táj drámaivá válik: meredek sziklafalak, dús trópusi növényzet és számos rejtett vízesés kíséri az utat. A terület régészeti szempontból is kiemelkedő, hiszen több tucat ősi Marae (szentély) és kőépítmény maradványait találták itt meg, amelyek a polinéz múlt titkait őrzik. Gazdasági szempontból is jelentős a hely, mivel itt üzemelnek a sziget legnagyobb vízerőművei, amelyek Tahiti áramellátásának gerincét adják. Papenoo azoknak ajánlott, akik a sziget vadabb, érintetlen arcát keresik.",
      ro: "Papenoo este un sat situat pe coasta de nord a insulei Tahiti, servind drept punct de acces principal către Valea Papenoo, cel mai mare bazin hidrografic și cea mai vastă zonă naturală protejată a insulei. Localitatea se află la gura de vărsare a râului Papenoo, un loc extrem de popular printre pasionații de surf datorită valurilor puternice care se formează pe plaja cu nisip negru vulcanic. Dincolo de sat, valea se deschide într-un peisaj spectaculos de munți abrupți și vegetație luxuriantă, adăpostind numeroase situri arheologice care atestă prezența vechilor civilizații polineziene sub formă de platforme ceremoniale Marae. Tot aici se află și o serie de hidrocentrale care joacă un rol crucial în furnizarea energiei electrice pentru întreaga insulă. Excursiile în interiorul văii dezvăluie cascade ascunse și bazine naturale ideale pentru scăldat, oferind o perspectivă autentică asupra geografiei tahitiene. Papenoo reprezintă echilibrul perfect între aventura în natură și conservarea patrimoniului istoric al Polineziei Franceze.",
      en: "Papenoo is a coastal village in northern Tahiti that serves as the strategic entrance to the island's vast interior through the Papenoo Valley. This valley, the largest on the island, is a prehistoric volcanic crater that now hosts the longest river in Tahiti. The village itself is situated at the river's mouth, where the meeting of freshwater and ocean currents creates world-class surfing conditions on its famous black sand beaches. Venturing inland from Papenoo leads to a rugged landscape of towering peaks and dense rainforests, where ancient archaeological sites, including stone Marae and residential terraces, are still being discovered. The valley is also an industrial hub for renewable energy, housing several major hydroelectric plants that power a significant portion of the island. For hikers and 4x4 enthusiasts, Papenoo is the ultimate base for exploring Tahiti’s untamed heart, offering access to hidden waterfalls and rare endemic flora far from the urban bustle of nearby Papeete.",
      es: "Papenoo es una ciudad en la costa norte de Tahití, al pie del Mont Orohena, la montaña más alta de la Polinesia Francesa. La economía se basa en la agricultura y el turismo. Papenoo tiene una iglesia, una escuela y un centro de salud. La población es de unos 1.500 habitantes. El lugar es conocido por el río Papenoo, que se utiliza para el rafting y el barranquismo. El monte Orohena (2.241 m) es un destino para los excursionistas. Los alrededores están marcados por una densa selva tropical.",
      pt: "Papenoo é uma cidade na costa norte do Taiti, no sopé do Mont Orohena, a montanha mais alta da Polinésia Francesa. A economia baseia-se na agricultura e no turismo. Papenoo tem uma igreja, uma escola e um centro de saúde. A população é de cerca de 1.500 habitantes. O local é conhecido pelo rio Papenoo, que é utilizado para rafting e canyoning. O monte Orohena (2.241 m) é um destino para caminhantes. Os arredores são caracterizados por uma densa floresta tropical.",
      fr: "Papenoo est une ville située sur la côte nord de Tahiti, au pied du mont Orohena, le plus haut sommet de la Polynésie française. L'économie repose sur l'agriculture et le tourisme. Papenoo dispose d'une église, d'une école et d'un centre de santé. La population est d'environ 1 500 habitants. La localité est réputée pour la rivière Papenoo, utilisée pour le rafting et le canyoning. Le mont Orohena (2 241 m) est une destination pour les randonneurs. Les environs sont marqués par une forêt tropicale dense.",
    },
