    imageHint: "Mahaena village coast and mountains Tahiti",
    descriptionAdvanced: {
      de: "Mahaena liegt an der wilderen Ostküste von Tahiti Nui und ist ein Ort von großer historischer Bedeutung. Im Jahr 1844 war das Dorf Schauplatz einer entscheidenden Schlacht während des französisch-tahitianischen Krieges, als tahitianische Krieger in den umliegenden Hügeln Widerstand gegen die Kolonialtruppen leisteten. Heute ist Mahaena ein Paradebeispiel für das traditionelle polynesische Landleben, fernab der touristischen Zentren von Papeete. Die fruchtbaren Böden der Region werden intensiv für den Anbau von Taro, Maniok und anderen Wurzelgemüsen genutzt, die auf den lokalen Märkten verkauft werden. Geografisch ist das Dorf durch einen schmalen Küstenstreifen geprägt, der direkt in die steilen, dicht bewaldeten Täler des Inselinneren übergeht. Die Küste hier ist bekannt für ihre schwarzen Sandstrände und die raue Brandung des Pazifiks, was dem Ort eine dramatische Atmosphäre verleiht. Besucher finden hier eine authentische Ruhe und können den Blick auf die unbewohnten Gebirgsketten Tahitis genießen, die oft in dichte Passatwolken gehüllt sind.",
      hu: "Mahaena Tahiti Nui keleti partján fekszik, és bár ma egy csendes mezőgazdasági falu, neve kitörölhetetlen a polinéz történelemből. 1844-ben itt zajlott a francia-tahiti háború egyik legjelentősebb ütközete, ahol a helyi ellenállók hősiesen küzdöttek a gyarmatosító csapatok ellen a falu feletti dombokon. A település ma az autentikus szigeti életmód őrzője; lakói főként mezőgazdaságból élnek, a környékbeli ültetvényeken nagy mennyiségben termesztenek tarót, jamszgyökeret és édesburgonyát. A falu elhelyezkedése különleges, hiszen egy keskeny sávban szorul a vad, hullámveréses óceánpart és a Tahiti belseje felé törő, áthatolhatatlan hegycsúcsok közé. A környék fekete homokos strandjai és a közeli völgyek érintetlen vízesései a természetközeli élményeket keresők számára vonzóak. Mahaena kiváló kiindulópont a sziget belső, lakatlan területeinek felfedezéséhez, ahol az ősi polinéz kultúra nyomai és a buja esőerdő dominál.",
      ro: "Mahaena este un sat pitoresc situat pe coasta de est a Tahiti Nui, o regiune cunoscută pentru peisajele sale sălbatice și autenticitatea păstrată. Localitatea a intrat în istorie în 1844, fiind locul unei bătălii sângeroase între forțele coloniale franceze și rezistența tahitiană, un eveniment care a marcat profund identitatea locală. În prezent, viața în Mahaena se desfășoară într-un ritm liniștit, comunitatea fiind axată pe agricultură tradițională. Solul vulcanic fertil permite cultivarea intensivă a tuberculilor precum taro și maniocul, esențiale în dieta polineziană. Geografia locului este marcată de fâșia îngustă de pământ cuprinsă între valurile puternice ale Pacificului și versanții muntoși abrupți, acoperiți de o vegetație tropicală deasă. Plajele cu nisip negru vulcanic din apropiere oferă un contrast vizual puternic cu verdele munților din fundal. Mahaena rămâne o destinație ideală pentru cei care doresc să descopere o latură a Tahiti mai puțin comercială, unde tradiția și respectul pentru pământ sunt încă pilonii societății.",
      en: "Mahaena, situated on the rugged windward coast of Tahiti Nui, is a place where history and nature converge. The village is most famously known as the site of the Battle of Mahaena in 1844, a major conflict of the Franco-Tahitian War where native warriors fiercely defended their land against French forces from fortified positions in the hills. Today, the village retains a peaceful, rural character, centered around traditional farming practices. The fertile volcanic soil of the area is ideal for growing root crops like taro and yams, which remain staples of the local economy. Nestled on a narrow strip of land between the pounding surf of the Pacific and the towering, emerald-green peaks of the interior, Mahaena offers breathtaking views of Tahiti's uninhabited mountainous heart. The coastline here is characterized by dramatic black sand beaches and a powerful ocean swell, making it a stark contrast to the calm lagoons of the west coast. It serves as an authentic window into Polynesian life, far removed from the modern bustle of Papeete.",
      es: "Mahaena es un asentamiento en la costa este de Tahití, conocido por sus plantaciones y su ambiente tranquilo. La economía se basa en la agricultura (vainilla, cocos) y la pesca. Mahaena tiene una iglesia y una escuela. La población es de unos 500 habitantes. El entorno es verde y montañoso. El lugar se encuentra cerca de la presa de Papenoo. La costa está bordeada de playas de arena negra. El turismo es limitado.",
      pt: "Mahaena é um assentamento na costa leste do Tahiti, conhecido pelas suas plantações e ambiente tranquilo. A economia baseia-se na agricultura (baunilha, cocos) e na pesca. Mahaena tem uma igreja e uma escola. A população é de cerca de 500 habitantes. O ambiente é verde e montanhoso. O local fica perto da barragem de Papenoo. A costa é ladeada por praias de areia preta. O turismo é limitado.",
      fr: "Mahaena est une localité de la côte est de Tahiti, connue pour ses plantations et son atmosphère paisible. L'économie repose sur l'agriculture (vanille, noix de coco) et la pêche. Mahaena dispose d'une église et d'une école. La population s'élève à environ 500 habitants. L'environnement est verdoyant et vallonné. Le village se situe à proximité du barrage de la Papenoo. La côte est bordée de plages de sable noir. Le tourisme y est restreint.",
    },
