      hu: ["Az évenkénti Tahiti Pro szörfversenyek helyszíne", "A 2024-es olimpiai szörfversenyek helyszíne", "Az úthálózat vége Tahiti Iti nyugati partján", "Egy történelmi törzsfőnöki csatáról nevezték el"],
      ro: ["Locul de desfășurare a competițiilor anuale Tahiti Pro", "Locația competițiilor de surf de la Jocurile Olimpice din 2024", "Capătul rețelei rutiere de pe coasta de vest a Tahiti Iti", "Numit după o bătălie istorică a căpeteniilor"],
