      fr: ["Lieu d'accueil des compétitions annuelles de surf Tahiti Pro", "Site des épreuves de surf des Jeux Olympiques de 2024", "Fin du réseau routier sur la côte ouest de Tahiti Iti", "Nommé d'après une bataille historique entre chefs"],
