    imageHint: "Teahupo'o giant wave surfing action",
    descriptionAdvanced: {
      de: "Teahupo'o ist ein abgelegenes Dorf an der Südwestküste von Tahiti Iti, dem kleineren Teil der Doppelinsel Tahiti. Weltweite Berühmtheit erlangte der Ort durch seine außergewöhnliche Brandung, die als eine der schwersten und gefährlichsten Wellen der Welt gilt. Das Phänomen entsteht durch ein extrem flaches Korallenriff, das abrupt aus der Tiefe des Ozeans ansteigt und die Wellen mit enormer Wucht brechen lässt. Der Name Teahupo'o bedeutet übersetzt etwa 'Mauer der Köpfe', was auf eine blutige Stammesfehde in der Geschichte des Ortes anspielt. Heute ist das Dorf das Zentrum der internationalen Surfszene und Austragungsort des jährlichen Billabong Pro Tahiti. Im Jahr 2024 war Teahupo'o zudem der offizielle Austragungsort der Surfwettbewerbe der Olympischen Spiele von Paris. Trotz des globalen Ruhms hat sich das Dorf seinen authentischen polynesischen Charakter bewahrt, da die Straße hier endet und das Hinterland nur per Boot oder zu Fuß zugänglich ist. Die umliegende Landschaft ist geprägt von schwarzen Sandstränden und steilen, tiefgrünen Bergen, die oft in den Wolken verschwinden.",
      hu: "Teahupo'o egy távoli település Tahiti Iti délnyugati partján, ahol a közúti hálózat véget ér, és átadja helyét az érintetlen természetnek. A falu a világ szörfös közösségének szentélye, köszönhetően a partjaitól néhány száz méterre törő, félelmetes hullámnak. Ez a hullám nem a magasságáról, hanem a vastagságáról és erejéről ismert, mivel egy rendkívül sekély korallzátonyon törik meg, hatalmas víztömeget mozgatva. A falu neve polinéz nyelven 'koponyák falát' jelenti, ami egy ősi törzsi csatára utal, ahol a győztesek falat emeltek az ellenség fejeiből. Teahupo'o ad otthont a rangos Tahiti Pro versenynek, és itt rendezték a 2024-es párizsi olimpia szörfversenyeit is, amihez egy különleges, ideiglenes bírói tornyot építettek a vízbe. A látogatók számára a környék a klasszikus polinéz paradicsomot kínálja: buja trópusi völgyek, vízesések és kristálytiszta lagúnák várják azokat, akik a szörfözésen túl a sziget belső nyugalmát is keresik. A helyi közösség szigorúan őrzi a falu csendjét és ökológiai egyensúlyát a tömegturizmussal szemben.",
      ro: "Teahupo'o este un sat pitoresc situat în districtul Taiarapu-Ouest, la capătul drumului principal de pe Tahiti Iti. Localitatea a devenit o legendă globală datorită valului său omonim, considerat cel mai greu și mai periculos din circuitul mondial de surf. Particularitatea acestui val este dată de reciful de corali foarte puțin adânc care forțează masa uriașă de apă să se prăbușească cu o forță incredibilă, creând tuburi spectaculoase. Numele său se traduce prin 'Zidul de cranii', amintind de o bătălie istorică între șefii locali de trib. Pe lângă competiția anuală Tahiti Pro, satul a găzduit probele de surf ale Jocurilor Olimpice din 2024, consolidându-și statutul de capitală mondială a acestui sport. Dincolo de spectacolul oferit de ocean, Teahupo'o este poarta de intrare către zona sălbatică Fenua Aihere, accesibilă doar cu barca, unde munții verzi cad abrupt în mare, formând cascade ascunse și peșteri marine. Atmosfera rămâne una tradițională, cu case modeste (fare) și o comunitate strâns legată de ritmul mareelor și al naturii tropicale luxuriante.",
      en: "Teahupo'o is a serene coastal village situated at the 'end of the road' on the southwestern peninsula of Tahiti Iti. It is world-renowned for its formidable surf break, widely regarded as one of the heaviest and most dangerous waves on the planet. The wave's unique power comes from the abrupt transition of the ocean floor from deep water to a very shallow, sharp coral reef, creating a thick, hollow barrel that attracts the elite of the surfing world. The name Teahupo'o literally translates to 'Wall of Skulls', referencing a historic tribal battle where the victor built a wall from the heads of the defeated. The village hosts the prestigious annual Tahiti Pro competition and served as the iconic venue for the surfing events of the 2024 Paris Olympic Games. Despite its global fame, Teahupo'o retains an authentic Polynesian charm, with no high-rise hotels or major tourist developments. Visitors can explore the lush valleys and dramatic cliffs of the Fenua Aihere region by boat, discovering hidden waterfalls and pristine lagoons that exemplify the raw beauty of French Polynesia.",
      es: "Teahupoo es un pueblo de la península de Tahiti Iti, mundialmente famoso por sus olas extremas que atraen cada año la competición de surf Billabong Pro Teahupo'o. La economía se basa en el turismo de surf y la agricultura. Teahupoo cuenta con una iglesia y un pequeño puerto deportivo. La población es de unos 500 habitantes. El pueblo está situado en una bahía protegida por arrecifes de coral. La ola Teahupoo es una de las más peligrosas del mundo, con barriles masivos.",
      pt: "Teahupoo é uma aldeia na península de Tahiti Iti, mundialmente famosa pelas suas ondas extremas que atraem todos os anos a competição de surf Billabong Pro Teahupo'o. A economia baseia-se no turismo de surf e na agricultura. Teahupoo tem uma igreja e uma pequena marina. A população é de cerca de 500 habitantes. A aldeia situa-se numa baía protegida por recifes de coral. A onda Teahupoo é uma das mais perigosas do mundo, com tubos massivos.",
      fr: "Teahupoo est un village de la presqu'île de Tahiti Iti, mondialement réputé pour ses vagues extrêmes qui attirent chaque année la compétition Billabong Pro Teahupo'o. L'économie repose sur le tourisme lié au surf et l'agriculture. Teahupoo possède une église et une petite marina. La population est d'environ 500 habitants. Le village se situe au bord d'une baie protégée par des récifs coralliens. La vague de Teahupo'o est l'une des plus redoutables au monde, formant des tubes massifs.",
    },
