      es: ["Ubicación de la playa 'Plage de Maui'", "Zona residencial importante para quienes trabajan en Taravao", "Conocido por su pesca en la laguna", "Ofrece una vista panorámica de Tahiti Nui"],
      pt: ["Localização da praia 'Plage de Maui'", "Importante zona residencial para quem trabalha em Taravao", "Conhecido pela sua pesca na lagoa", "Oferece uma vista panorâmica do Tahiti Nui"],
