    imageHint: "Plage de Maui white sand beach Toahotu",
    descriptionAdvanced: {
      de: "Toahotu ist eine malerische Gemeinde am Übergang zwischen Tahiti Nui und der kleineren Halbinsel Tahiti Iti. Der Ort dient als Tor zu einer wilderen und unberührteren Seite Tahitis, die für ihre steilen grünen Berge und tiefblauen Buchten bekannt ist. Eine der Hauptattraktionen von Toahotu ist der Plage de Maui, einer der wenigen weißen Sandstrände der Insel, der einen starken Kontrast zum sonst üblichen schwarzen Vulkansand bildet. Die Einwohner leben traditionell von der Lagunenfischerei und der Landwirtschaft, wobei Kokosplantagen das Landschaftsbild prägen. In Toahotu herrscht eine deutlich ruhigere Atmosphäre als in der Hauptstadt Papeete, was es zu einem beliebten Wohnort für Pendler macht, die in der nahegelegenen Stadt Taravao arbeiten. Von der Küste aus bietet sich ein beeindruckender Panoramablick auf das Gebirge von Tahiti Nui, besonders während der goldenen Stunde vor dem Sonnenuntergang.",
      hu: "Toahotu egy festői község Tahiti Nui és a kisebb Tahiti Iti félsziget találkozásánál. A település kapuként szolgál Tahiti vadabb, érintetlenebb oldala felé, amelyet meredek zöld hegyek és mélykék öblök jellemeznek. Toahotu egyik legnépszerűbb pontja a Plage de Maui, amely a sziget kevés fehér homokos strandjainak egyike, látványos kontrasztot alkotva a vulkanikus eredetű fekete homokkal. A helyiek életmódja szorosan kötődik a tengerhez és a földhöz; a lagúnai halászat és a kiterjedt kókuszültetvények meghatározzák a falu mindennapjait. Toahotu légköre sokkal nyugodtabb és hagyományosabb, mint a fővárosé, Papeete-é, így kedvelt lakóhely az ingázók számára is. A partvonal mentén sétálva lenyűgöző panoráma nyílik Tahiti Nui fenséges hegyvonulataira, amely a lemenő nap fényében nyújtja a legszebb látványt az idelátogatók számára.",
      ro: "Toahotu este o comună pitorească situată la intrarea în peninsula Tahiti Iti, reprezentând tranziția către partea mai sălbatică și mai puțin explorată a insulei Tahiti. Localitatea este renumită pentru Plage de Maui, una dintre puținele plaje cu nisip alb de pe insulă, oferind un contrast spectaculos cu nisipul vulcanic negru specific regiunii. Viața în Toahotu păstrează un ritm tradițional, localnicii bazându-se pe pescuitul în lagună și pe exploatarea plantațiilor de cocos care domină peisajul. Datorită atmosferei sale liniștite și a proximității față de centrul comercial Taravao, comuna a devenit o zonă rezidențială căutată. Vizitatorii sunt atrași aici de frumusețea naturală intactă și de posibilitatea de a explora coasta de sud. De pe țărm, se poate admira o vedere panoramică superbă asupra munților maiestuoși din Tahiti Nui, oferind o perspectivă unică asupra geografiei dramatice a Polineziei Franceze.",
      en: "Toahotu is a scenic commune located at the neck of the Tahiti Iti peninsula, serving as the gateway to the more rugged and untouched southern half of the island. Known for its laid-back atmosphere and lush surroundings, the village is a prime example of the traditional Tahitian lifestyle. One of its most famous features is the Plage de Maui, a rare white sand beach that stands out against the island's more common volcanic black sands. The local economy is deeply rooted in lagoon fishing and agriculture, with vast coconut groves blanketing the coastal plains. Toahotu offers a peaceful retreat from the bustling capital of Papeete, making it a popular residential area for those working in nearby Taravao. From its shores, visitors can enjoy stunning panoramic views of the mountains of Tahiti Nui, especially as the sun sets over the Pacific, illuminating the island's dramatic volcanic peaks.",
      es: "Toahotu es un asentamiento en la península de Tahiti Iti, conocido por su producción agrícola y su estilo de vida tradicional. La economía se basa en la agricultura (cocos, vainilla) y la pesca. Toahotu tiene una iglesia y una escuela. La población es de aproximadamente 500 habitantes. El entorno es montañoso con plantaciones. El lugar está alejado de las rutas turísticas principales. La costa ofrece playas de arena negra. La vida tiene un carácter rural.",
      pt: "Toahotu é uma povoação na península de Tahiti Iti, conhecida pela sua produção agrícola e modo de vida tradicional. A economia baseia-se na agricultura (cocos, baunilha) e na pesca. Toahotu tem uma igreja e uma escola. A população é de cerca de 500 habitantes. O ambiente é montanhoso, com plantações. A localidade fica fora das principais rotas turísticas. A costa oferece praias de areia negra. A vida tem uma forte marca rural.",
      fr: "Toahotu est un village sur la presqu'île de Tahiti Iti, connu pour sa production agricole et son mode de vie traditionnel. L'économie repose sur l'agriculture (noix de coco, vanille) et la pêche. Toahotu possède une église et une école. La population est d'environ 500 habitants. Les environs sont vallonnés avec des plantations. Le lieu se trouve à l'écart des grands flux touristiques. La côte propose des plages de sable noir. La vie y est marquée par la ruralité.",
    },
