      hu: "Afaahiti egy község a Tahiti Iti félszigeten, amely határos Taravao fontos kereskedelmi központjával.",
      ro: "Afaahiti este o comună de pe peninsula Tahiti Iti, care se învecinează cu importantul centru comercial Taravao.",
      en: "Afaahiti is a commune on the Tahiti Iti peninsula, bordering the important commercial center of Taravao.",
      es: "Afaahiti es un municipio de la península de Tahiti Iti, que limita con el importante centro comercial de Taravao.",
      pt: "Afaahiti é um município na península de Tahiti Iti, que faz fronteira com o importante centro comercial de Taravao.",
      fr: "Afaahiti est une commune de la presqu'île de Tahiti Iti, bordant l'important centre commercial de Taravao.",
