    imageHint: "Taravao plateau green pastures Afaahiti",
    descriptionAdvanced: {
      de: "Afaahiti ist eine malerische Gemeinde an der Nordostküste der Halbinsel Tahiti Iti, dem kleineren Teil der Insel Tahiti. Sie liegt strategisch günstig direkt neben Taravao, dem wirtschaftlichen Knotenpunkt, der die beiden Halinseln verbindet. Afaahiti ist besonders für das Plateau von Taravao bekannt, eine üppig grüne Hochebene, die aufgrund ihres kühleren Klimas und der sanften Hügel oft als 'kleine Normandie' bezeichnet wird. Dieses Plateau ist ein Zentrum für die lokale Viehzucht und Landwirtschaft, was für das sonst eher tropisch-maritime Französisch-Polynesien ungewöhnlich ist. Die Gemeinde beherbergt zudem wichtige Bildungseinrichtungen und bietet von vielen Aussichtspunkten aus einen spektakulären Blick auf beide Küsten von Tahiti – sowohl die Nord- als auch die Südküste. Für Reisende ist Afaahiti der ideale Ausgangspunkt, um die wildere, weniger erschlossene Seite von Tahiti Iti zu erkunden, wo steile Klippen und dichte Regenwälder das Landschaftsbild prägen.",
      hu: "Afaahiti egy gyönyörű község Tahiti Iti északkeleti részén, amely közvetlenül határos a félsziget kapujaként ismert Taravao városával. A település különlegessége a Taravao-fennsík, amely dús legelőivel és hűvösebb klímájával egyfajta európai mezőgazdasági tájat idéz a trópusok közepén. Ez a terület a sziget tejtermelésének és állattenyésztésének központja, ahol a tehenek legelésznek a zöld dombokon. Afaahiti fontos oktatási központ is, több középiskola és intézmény található itt, amelyek a környék fiataljait szolgálják. A látogatók számára a település legfőbb vonzereje a lélegzetelállító panoráma: a magasabb pontokról egyszerre látható Tahiti Iti északi és déli partvonala, valamint az óceán végtelensége. Afaahiti tökéletes kiindulópont Tahiti Iti vadregényes tájainak felfedezéséhez, ahol a hagyományos polinéz életmód és a modern gazdasági tevékenység harmonikusan él egymás mellett.",
      ro: "Afaahiti este o comună situată pe coasta de nord-est a peninsulei Tahiti Iti, fiind una dintre porțile de acces către partea mai sălbatică a insulei Tahiti. Localitatea se învecinează direct cu Taravao, punctul strategic care face legătura între Tahiti Nui și Tahiti Iti. Una dintre principalele atracții ale zonei este Platoul Taravao, o regiune înaltă cu pășuni verzi și o climă mai răcoroasă, care a devenit centrul zootehniei și agriculturii din regiune, amintind vizitatorilor de peisajele rurale europene. Pe lângă rolul său agricol, Afaahiti este și un centru educațional important, găzduind mai multe școli care deservesc comunitățile din peninsulă. Din punctele sale de observație, se pot admira priveliști panoramice spectaculoase asupra ambelor coaste ale peninsulei, oferind un unghi unic asupra reliefului vulcanic al insulei. Pentru turiști, Afaahiti reprezintă locul ideal pentru a începe explorarea drumurilor lăturalnice și a plajelor ascunse din Tahiti Iti, departe de agitația capitalei Papeete.",
      en: "Afaahiti is a picturesque commune located on the northeastern coast of the Tahiti Iti peninsula, bordering the busy transit town of Taravao. It is most famous for the Plateau de Taravao, a lush highland area characterized by rolling green pastures and a temperate climate that stands in contrast to the tropical lowlands. This plateau serves as the heart of French Polynesia's dairy and livestock industry, giving the area a unique rural atmosphere often compared to the countryside of Normandy. Afaahiti is also an important educational hub for the region, hosting several secondary schools and vocational centers. From elevated spots throughout the commune, visitors can enjoy breathtaking panoramic views of both the northern and southern coasts of the peninsula simultaneously. As a gateway to the more rugged and traditional Tahiti Iti, Afaahiti offers travelers a chance to experience the authentic agricultural lifestyle of the island while enjoying some of its most diverse and stunning landscapes.",
      es: "Afaahiti es un municipio de la península de Tahiti Iti, conocido por su bahía y su producción agrícola. La economía se basa en la agricultura (cocos, piñas) y la pesca. Afaahiti cuenta con una iglesia y una escuela. La población es de unos 1.000 habitantes. La bahía de Afaahiti es un fondeadero protegido. El entorno está caracterizado por plantaciones y colinas. El lugar es accesible desde Papeete a través de la carretera costera.",
      pt: "Afaahiti é um município na península de Tahiti Iti, conhecido pela sua baía e produção agrícola. A economia baseia-se na agricultura (cocos, ananás) e na pesca. Afaahiti tem uma igreja e uma escola. A população é de cerca de 1.000 habitantes. A baía de Afaahiti é um ancoradouro protegido. Os arredores são caracterizados por plantações e colinas. O local é acessível a partir de Papeete através da estrada costeira.",
      fr: "Afaahiti est une commune de la presqu'île de Tahiti Iti, connue pour sa baie et sa production agricole. L'économie est basée sur l'agriculture (noix de coco, ananas) et la pêche. Afaahiti possède une église et une école. La population s'élève à environ 1 000 habitants. La baie d'Afaahiti est un mouillage protégé. Les environs sont caractérisés par des plantations et des collines. Le lieu est accessible depuis Papeete par la route côtière.",
    },
