    facts: {
      de: ["Ort mit traditioneller polynesischer Atmosphäre", "Wichtiger Punkt für den Anbau von Vanille", "Besitzt eine kleine, malerische Kirche", "Beliebt bei Wanderern für Küstentouren"],
      hu: ["Hagyományos polinéz hangulatú hely", "A vaníliatermesztés fontos helyszíne", "Kicsi, festői temploma van", "Népszerű a tengerparti túrákat kedvelők körében"],
      ro: ["Loc cu o atmosferă tradițională polineziană", "Punct important pentru cultivarea vaniliei", "Deține o biserică mică și pitorească", "Popular printre excursioniști pentru tururile de coastă"],
      en: ["Place with a traditional Polynesian atmosphere", "Important point for vanilla cultivation", "Features a small, picturesque church", "Popular with hikers for coastal tours"],
      es: ["Lugar con atmósfera tradicional polinesia", "Punto importante para el cultivo de vainilla", "Posee una pequeña y pintoresca iglesia", "Popular entre los excursionistas por las rutas costeras"],
      pt: ["Local com atmosfera tradicional polinésia", "Ponto importante para o cultivo de baunilha", "Possui uma pequena e pitoresca igreja", "Popular entre os caminhantes para passeios costeiros"],
      fr: ["Lieu à l'atmosphère polynésienne traditionnelle", "Point important pour la culture de la vanille", "Possède une petite église pittoresque", "Apprécié des randonneurs pour ses circuits côtiers"],
    },
    imageHint: "Pueu village coastline and mountains",
    descriptionAdvanced: {
      de: "Pueu ist ein malerisches Dorf an der Nordküste von Tahiti Iti, dem kleineren Teil der Insel Tahiti. Abseits der geschäftigen Hauptstadt Papeete bietet Pueu eine Oase der Ruhe und eine tief verwurzelte polynesische Atmosphäre. Die Region ist bekannt für ihre fruchtbaren Böden und üppigen Gärten, in denen insbesondere Vanille angebaut wird. Wanderer schätzen die Küstenpfade, die spektakuläre Ausblicke auf den Pazifik und die grünen Berge des Hinterlandes bieten. Im Zentrum des Dorfes befindet sich eine kleine, charakteristische Kirche, die das soziale Leben der Gemeinschaft widerspiegelt. Die umliegenden Korallenriffe sind ideal zum Schnorcheln und bieten Schutz für eine Vielzahl tropischer Meeresbewohner. Pueu ist der perfekte Ort, um das traditionelle Leben auf Französisch-Polynesien kennenzulernen, wo Fischfang und Landwirtschaft noch immer die wichtigsten Lebensgrundlagen darstellen. Die Gastfreundschaft der Bewohner und die unberührte Natur machen diesen Ort zu einem Geheimtipp für Individualreisende.",
      hu: "Pueu egy festői szépségű falu Tahiti Iti északi partján, amely Tahiti szigetének kisebb, vadregényesebb részét alkotja. A település távol esik a főváros, Papeete zajától, így megőrizte nyugodt, hagyományos polinéz jellegét. Pueu híres termékeny talajáról és buja kertjeiről, ahol a mai napig jelentős a vanília termesztése. A falu központjában álló kis templom és a színes házak barátságos hangulatot árasztanak. A környék kiváló lehetőségeket nyújt a túrázásra; a part menti ösvényekről lenyűgöző kilátás nyílik a Csendes-óceánra és a belső területek meredek, zöldellő hegyoldalaira. A közeli korallzátonyok gazdag élővilága vonzza a búvárkodás szerelmeseit. Pueu lakói főként halászatból és mezőgazdaságból élnek, így az ide látogatók betekintést nyerhetnek az autentikus szigetlakó életmódba. A település ideális kiindulópont Tahiti Iti eldugott öbleinek és vízeséseinek felfedezéséhez.",
      ro: "Pueu este un sat pitoresc situat pe coasta de nord a Tahiti Iti, brațul mai mic și mai sălbatic al insulei Tahiti. Departe de agitația capitalei Papeete, Pueu oferă o atmosferă autentică și liniștită, fiind înconjurat de o vegetație luxuriantă și grădini pline de flori tropicale. Localitatea este un punct important pentru cultivarea vaniliei, o îndeletnicire tradițională care parfumează aerul în perioadele de recoltare. Satul găzduiește o biserică mică și fermecătoare, care reprezintă inima comunității locale. Pentru iubitorii de natură, Pueu oferă trasee de drumeție de-a lungul coastei, care dezvăluie priveliști spectaculoase asupra recifelor de corali și a munților verzi din interior. Apele din apropiere sunt ideale pentru snorkeling, adăpostind numeroase specii de pești tropicali. Viața în Pueu se desfășoară într-un ritm lent, bazat pe pescuit și agricultură, oferind vizitatorilor șansa de a experimenta ospitalitatea polineziană veritabilă într-un cadru natural de o frumusețe rară.",
      en: "Pueu is a charming coastal village situated on the northern shore of Tahiti Iti, the smaller, more rugged peninsula of Tahiti. Located well away from the bustle of Papeete, Pueu maintains a tranquil, traditional Polynesian atmosphere. The village is renowned for its lush surroundings and fertile soil, making it a key area for the cultivation of high-quality Tahitian vanilla. Visitors are often drawn to the scenic coastal trails that offer breathtaking views of the Pacific Ocean and the steep, emerald-green mountains of the interior. In the heart of the village stands a small, picturesque church that serves as a central gathering point for the tight-knit community. The offshore coral reefs provide excellent opportunities for snorkeling and diving, showcasing a rich variety of marine biodiversity. Life in Pueu revolves around the sea and the land, offering an authentic glimpse into French Polynesian culture, where traditional fishing methods and sustainable agriculture are still very much a part of daily existence.",
      es: "Pueu es un municipio en la península de Tahiti Iti, conocido por sus playas de arena negra y su estilo de vida tradicional. La economía se basa en la agricultura y la pesca. Pueu tiene una iglesia y una escuela. La población es de unos 800 habitantes. El lugar se encuentra en una bahía protegida por arrecifes de coral. El entorno es verde y ondulado. El turismo es escaso, pero existen oportunidades para el snorkel y el senderismo.",
      pt: "Pueu é um município na península de Tahiti Iti, conhecido pelas suas praias de areia preta e pelo estilo de vida tradicional. A economia baseia-se na agricultura e na pesca. Pueu tem uma igreja e uma escola. A população é de cerca de 800 habitantes. O local situa-se numa baía protegida por recifes de coral. O ambiente é verde e montanhoso. O turismo é reduzido, mas existem oportunidades para snorkeling e caminhadas.",
      fr: "Pueu est une commune de la presqu'île de Tahiti Iti, connue pour ses plages de sable noir et son mode de vie traditionnel. L'économie repose sur l'agriculture et la pêche. Pueu dispose d'une église et d'une école. La population est d'environ 800 habitants. Le village est situé au bord d'une baie protégée par des récifs coralliens. L'environnement est verdoyant et vallonné. Le tourisme y est peu développé, mais il existe des possibilités de plongée avec tuba et de randonnée.",
    },
