      pt: ["Local da expedição espanhola de 1774", "Robert Louis Stevenson passou aqui vários meses", "Conhecida pela praia de areia preta no rio Vaitepiha", "Porta de entrada para a costa selvagem de Pari"],
      fr: ["Lieu de l'expédition espagnole de 1774", "Robert Louis Stevenson y passa plusieurs mois", "Célèbre pour sa plage de sable noir à l'embouchure de la Vaitepiha", "Porte d'entrée vers la côte sauvage du Pari"],
