      pt: ["Local da igreja europeia mais antiga da Polinésia", "Antiga sede real da dinastia Pomare", "Situada perto de importantes locais de observação de golfinhos", "Possui uma construção octogonal marcante"],
      fr: ["Site de la plus ancienne église européenne de Polynésie", "Ancien siège royal de la dynastie Pomare", "Situé à proximité de sites majeurs d'observation des dauphins", "Possède une structure octogonale distinctive"],
