      en: ["The Marae Papetoai was built in 1750.", "Papetoai Bay covers an area of about 3 km².", "The average depth of the lagoon is 5 meters.", "Papetoai has 823 inhabitants (2017 census).", "Coconut production on Moorea is 1,200 tons annually.", "Water temperature is a constant 26°C year-round."],
      es: ["El Marae Papetoai fue erigido en el año 1750.", "La bahía de Papetoai tiene una superficie de unos 3 km².", "La profundidad media de la laguna es de 5 metros.", "Papetoai tiene 823 habitantes (año 2017).", "La producción de coco en Moorea es de 1.200 toneladas anuales.", "La temperatura del agua es de 26°C durante todo el año."],
      pt: ["O Marae Papetoai foi construído no ano 1750.", "A baía de Papetoai tem uma área de cerca de 3 km².", "A profundidade média da lagoa é de 5 metros.", "Papetoai tem 823 habitantes (em 2017).", "A produção de coco em Moorea é de 1.200 toneladas por ano.", "A temperatura da água é de 26°C durante todo o ano."],
      fr: ["Le Marae Papetoai a été construit en 1750.", "La baie de Papetoai a une superficie d'environ 3 km².", "La profondeur moyenne du lagon est de 5 mètres.", "Papetoai compte 823 habitants (chiffre 2017).", "La production de noix de coco à Moorea est de 1 200 tonnes par an.", "La température de l'eau est de 26°C toute l'année."],
