      ro: ["Centru pentru construcția de canoe tradiționale", "Slăvit pentru valul de clasă mondială de la pasul Haapiti", "Găzduiește Centrul Cultural Tiki Village", "Păstrează o atmosferă foarte tradițională"],
      en: ["Center for traditional canoe building", "Famous for the world-class wave at Haapiti Pass", "Home to the Tiki Village Cultural Center", "Preserves a very traditional atmosphere"],
