      pt: ["Centro para a construção de canoas tradicionais", "Famoso pela onda de classe mundial na passagem de Haapiti", "Abriga o Centro Cultural Tiki Village", "Preserva uma atmosfera muito tradicional"],
      fr: ["Centre de construction de pirogues traditionnelles", "Célèbre pour sa vague de classe mondiale à la passe de Haapiti", "Abrite le centre culturel Tiki Village", "Préserve une atmosphère très traditionnelle"],
