      pt: ["O porto de Vaiare foi inaugurado em 1965.", "Partem diariamente 8 ferries de Vaiare para o Tahiti.", "A travessia para o Tahiti demora cerca de 30 minutos.", "A praia de Vaiare tem 500 m de comprimento.", "A população é de 398 habitantes (dados de 2017).", "A profundidade da água no porto é de 4 metros."],
