    imageHint: "Tevaitoa village Raiatea landscape",
    descriptionAdvanced: {
      de: "Tevaitoa ist ein Dorf auf der Insel Raivavae in Französisch-Polynesien, gelegen an der Westküste. Die Siedlung ist bekannt für ihren langen weißen Sandstrand, der sich über mehrere Kilometer erstreckt. Tevaitoa ist ein Zentrum der Kopra-Produktion, die aus den zahlreichen Kokospalmenhainen gewonnen wird. Die lokale Bevölkerung lebt hauptsächlich von der Landwirtschaft und der Fischerei. Historisch war Tevaitoa Standort eines bedeutenden Marae, der heute als archäologische Stätte geschützt ist. Die französische Kolonialverwaltung baute im 19. Jahrhundert ein Verwaltungsgebäude, das heute als Museum dient. Tevaitoa hat eine kleine Kirche, eine Grundschule und ein Gesundheitszentrum. Der Tourismus ist noch wenig entwickelt, aber es gibt einige Übernachtungsmöglichkeiten. Die Lagune ist ideal zum Schnorcheln und Tauchen mit reicher Korallenvielfalt. Die Insel Raivavae ist bekannt für ihre endemischen Vogelarten, die in den Wäldern rund um Tevaitoa beobachtet werden können.",
      hu: "Tevaitoa egy falu Raivavae szigetén, Francia Polinéziában, a nyugati parton. A település híres hosszú fehér homokos strandjáról, amely több kilométeren át húzódik. Tevaitoa a kopratermelés központja, amelyet a számos kókuszpálma ligetből nyernek. A helyi lakosság főként mezőgazdaságból és halászatból él. Történelmileg Tevaitoa egy jelentős marae helyszíne volt, amely ma régészeti lelőhelyként védett. A francia gyarmati kormányzat a 19. században közigazgatási épületet épített, amely ma múzeumként szolgál. Tevaitoa-ban van egy kis templom, egy általános iskola és egy egészségügyi központ. A turizmus még kevéssé fejlett, de van néhány szálláslehetőség. A lagúna ideális sznorkelezéshez és búvárkodáshoz gazdag korallvilággal. Raivavae szigete endemikus madárfajairól ismert, amelyek a Tevaitoa körüli erdőkben figyelhetők meg.",
      ro: "Tevaitoa este un sat pe insula Raivavae din Polinezia Franceză, situat pe coasta de vest. Așezarea este cunoscută pentru plaja lungă de nisip alb care se întinde pe câțiva kilometri. Tevaitoa este un centru de producție de copra, obținută din numeroasele plantații de palmieri de cocos. Populația locală trăiește în principal din agricultură și pescuit. Din punct de vedere istoric, Tevaitoa a fost locul unui marae important, acum protejat ca sit arheologic. Administrația colonială franceză a construit o clădire administrativă în secolul al XIX-lea, care acum servește ca muzeu. Tevaitoa are o biserică mică, o școală primară și un centru de sănătate. Turismul este încă puțin dezvoltat, dar există câteva opțiuni de cazare. Laguna este ideală pentru snorkeling și scufundări, cu o diversitate bogată de corali. Insula Raivavae este cunoscută pentru speciile endemice de păsări care pot fi observate în pădurile din jurul Tevaitoa.",
      en: "Tevaitoa is a village on the island of Raivavae in French Polynesia, located on the west coast. The settlement is known for its long white sand beach that stretches for several kilometers. Tevaitoa is a center of copra production, obtained from the numerous coconut groves. The local population lives mainly from agriculture and fishing. Historically, Tevaitoa was the site of an important marae, now protected as an archaeological site. The French colonial administration built an administrative building in the 19th century, now serving as a museum. Tevaitoa has a small church, a primary school, and a health center. Tourism is still underdeveloped, but there are some accommodation options. The lagoon is ideal for snorkeling and diving with rich coral diversity. Raivavae island is known for its endemic bird species, which can be observed in the forests around Tevaitoa.",
      es: "Tevaitoa es un pueblo de la isla de Raivavae, en la Polinesia Francesa, situado en la costa oeste. El asentamiento es conocido por su larga playa de arena blanca que se extiende a lo largo de varios kilómetros. Tevaitoa es un centro de producción de copra, obtenida de los numerosos cocoteros. La población local vive principalmente de la agricultura y la pesca. Históricamente, Tevaitoa fue el lugar de un importante Marae, hoy protegido como yacimiento arqueológico. La administración colonial francesa construyó un edificio administrativo en el siglo XIX que hoy sirve de museo. Tevaitoa tiene una pequeña iglesia, una escuela primaria y un centro de salud. El turismo está poco desarrollado, pero hay algunos alojamientos. La laguna es ideal para el buceo con tubo y el submarinismo con una rica variedad de corales. La isla de Raivavae es conocida por sus especies de aves endémicas, que pueden observarse en los bosques que rodean Tevaitoa.",
      pt: "Tevaitoa é uma aldeia na ilha de Raivavae, na Polinésia Francesa, localizada na costa leste. O povoado é conhecido pela sua longa praia de areia branca, que se estende por vários quilómetros. Tevaitoa é um centro de produção de copra, obtida a partir dos numerosos coqueirais. A população local vive principalmente da agricultura e da pesca. Historicamente, Tevaitoa foi o local de um importante Marae, que hoje é protegido como sítio arqueológico. A administração colonial francesa construiu um edifício administrativo no século XIX, que hoje serve de museu. Tevaitoa tem uma pequena igreja, uma escola primária e um centro de saúde. O turismo ainda está pouco desenvolvido, mas existem algumas opções de alojamento. A lagoa é ideal para mergulho com snorkel e mergulho com cilindro, com uma rica diversidade de corais. A ilha de Raivavae é conhecida pelas suas espécies de aves endémicas, que podem ser observadas nas florestas ao redor de Tevaitoa.",
      fr: "Tevaitoa est un village sur l'île de Raivavae, en Polynésie française, situé sur la côte ouest. L'établissement est réputé pour sa longue plage de sable blanc qui s'étend sur plusieurs kilomètres. Tevaitoa est un centre de production de coprah, issu des nombreuses cocoteraies. La population locale vit principalement de l'agriculture et de la pêche. Historiquement, Tevaitoa abritait un important Marae, aujourd'hui protégé en tant que site archéologique. L'administration coloniale française y a construit au XIXe siècle un bâtiment administratif qui sert aujourd'hui de musée. Tevaitoa possède une petite église, une école primaire et un centre de santé. Le tourisme est encore peu développé, mais il existe quelques possibilités d'hébergement. Le lagon est idéal pour le snorkeling et la plongée avec sa grande diversité de coraux. L'île de Raivavae est connue pour ses espèces d'oiseaux endémiques, que l'on peut observer dans les forêts entourant Tevaitoa.",
    },
