      ro: ["Deține o stație importantă de protecție a țestoaselor", "Port important pentru ambarcațiunile cu vele în golful adânc", "Centru pentru fermele de vanilie și perle", "Situat pitoresc între munți abrupți"],
      en: ["Features an important turtle protection sanctuary", "Major harbor for sailboats in the deep bay", "Hub for vanilla and pearl farms", "Pictureresquely located between steep mountains"],
