      pt: ["A praia de areia preta tem 800 m de comprimento.", "A produção de baunilha em Raiatea é de 1 tonelada anual.", "Haamene tem 298 habitantes (dados de 2017).", "O festival realiza-se em julho.", "A profundidade da água em frente à praia é de 2 metros.", "As plantações de café cobrem 10 hectares."],
