      pt: ["A praia de Faaaha tem 1,2 km de comprimento.", "A igreja de Faaaha foi construída em 1856.", "Faaaha tem 310 habitantes (2017).", "A lagoa abriga cerca de 50 tartarugas marinhas.", "A colheita de baunilha na região é de 2 toneladas.", "A festa das tartarugas realiza-se em novembro."],
      fr: ["La plage de Faaaha est longue de 1,2 km.", "L'église de Faaaha a été construite en 1856.", "Faaaha compte 310 habitants (2017).", "Le lagon abrite environ 50 tortues marines.", "La récolte de vanille dans la région s'élève à 2 tonnes.", "La fête de la tortue a lieu en novembre."],
