      ro: ["Huahine are o suprafață de 75 km².", "Marae de la Maeva datează din secolul al XVI-lea.", "Maeva are 612 locuitori (recensământ 2017).", "Biserica a fost construită în 1845.", "Laguna are o adâncime de până la 10 metri.", "Festivalul Huahine are loc în octombrie."],
      en: ["Huahine has an area of 75 km².", "The marae of Maeva dates from the 16th century.", "Maeva has 612 inhabitants (2017 census).", "The church was built in 1845.", "The lagoon is up to 10 meters deep.", "The Huahine Festival takes place in October."],
      es: ["Huahine tiene una superficie de 75 km².", "El marae de Maeva data del siglo XVI.", "Maeva tiene 612 habitantes (según 2017).", "La iglesia fue construida en 1845.", "La laguna tiene hasta 10 metros de profundidad.", "El festival de Huahine se celebra en octubre."],
      pt: ["Huahine tem uma área de 75 km².", "O marae de Maeva data do século XVI.", "Maeva tem 612 habitantes (dados de 2017).", "A igreja foi construída em 1845.", "A lagoa tem até 10 metros de profundidade.", "O festival de Huahine ocorre em outubro."],
      fr: ["Huahine s'étend sur une superficie de 75 km².", "Le marae de Maeva date du XVIe siècle.", "Maeva compte 612 habitants (en 2017).", "L'église a été construite en 1845.", "Le lagon atteint jusqu'à 10 mètres de profondeur.", "Le festival de Huahine a lieu en octobre."],
