    imageHint: "Parea beach and turquoise lagoon Huahine Iti",
    descriptionAdvanced: {
      de: "Parea ist ein Dorf auf der Insel Huahine in Französisch-Polynesien, gelegen an der Nordküste. Die Siedlung ist bekannt für ihren langen weißen Sandstrand und die ruhige Lagune, die ideal zum Schwimmen und Segeln ist. Parea ist landwirtschaftlich geprägt, mit Anbau von Kokosnüssen, Vanille und Wassermelonen. Die Wirtschaft basiert auf Landwirtschaft und Tourismus. Die Einwohnerzahl beträgt etwa 200. Historisch war Parea ein wichtiger Hafen für den interinsularen Handel. Die französische Mission errichtete eine Kirche im 19. Jahrhundert. Parea hat eine Grundschule und ein Postamt. Die Lagune beherbergt eine große Population von Stachelrochen. Der Tourismus konzentriert sich auf umweltfreundliche Resorts und Eco-Lodges. Die lokale Küche ist bekannt für ihre frischen Meeresfrüchte. Jährlich findet ein Rochenfest statt, das die Bedeutung dieser Tiere für die lokale Kultur würdigt. Wanderungen durch die tropischen Wälder bieten Einblicke in die einheimische Flora und Fauna.",
      hu: "Parea egy falu Huahine szigetén, Francia Polinéziában, az északi parton. A település híres hosszú fehér homokos strandjáról és csendes lagúnájáról, amely ideális úszáshoz és vitorlázáshoz. Parea mezőgazdasági jellegű, kókuszdió, vanília és görögdinnye termesztésével. A gazdaság mezőgazdaságon és turizmuson alapul. A lakosság körülbelül 200 fő. Történelmileg Parea fontos kikötő volt a szigetek közötti kereskedelem számára. A francia misszió a 19. században templomot épített. Parea-ban van egy általános iskola és egy posta. A lagúna nagyszámú tüskésrájának ad otthont. A turizmus környezetbarát üdülőhelyekre és öko-lodge-okra összpontosul. A helyi konyha friss tenger gyümölcseiről ismert. Évente Rája Fesztivált rendeznek, amely elismeri ezen állatok jelentőségét a helyi kultúrában. A trópusi erdőkön keresztüli túrák betekintést nyújtanak az őshonos növény- és állatvilágba.",
      ro: "Parea este un sat pe insula Huahine din Polinezia Franceză, situat pe coasta de nord. Așezarea este cunoscută pentru plaja lungă de nisip alb și laguna liniștită, ideală pentru înot și navigație. Parea este predominant agricol, cu cultivare de nuci de cocos, vanilie și pepeni verzi. Economia se bazează pe agricultură și turism. Populația este de aproximativ 200 de persoane. Din punct de vedere istoric, Parea a fost un port important pentru comerțul inter-insular. Misiunea franceză a construit o biserică în secolul al XIX-lea. Parea are o școală primară și un oficiu poștal. Laguna găzduiește o populație mare de raze spintecate. Turismul se concentrează pe stațiuni ecologice și eco-lodge-uri. Bucătăria locală este cunoscută pentru fructele de mare proaspete. Anual are loc un Festival al Razelor care onorează importanța acestor animale în cultura locală. Drumețiile prin pădurile tropicale oferă perspective asupra florei și faunei indigene.",
      en: "Parea is a village on the island of Huahine in French Polynesia, located on the north coast. The settlement is known for its long white sand beach and calm lagoon, ideal for swimming and sailing. Parea is agricultural, with cultivation of coconuts, vanilla, and watermelons. The economy relies on agriculture and tourism. The population is about 200. Historically, Parea was an important port for inter-island trade. The French mission built a church in the 19th century. Parea has a primary school and a post office. The lagoon hosts a large population of stingrays. Tourism focuses on eco-friendly resorts and eco-lodges. Local cuisine is known for its fresh seafood. An annual Stingray Festival honors the importance of these animals in local culture. Hikes through tropical forests offer insights into native flora and fauna.",
      es: "Parea es un pueblo de la isla de Huahine, en la Polinesia Francesa, situado en la costa norte. El asentamiento es conocido por su larga playa de arena blanca y su laguna tranquila, ideal para nadar y navegar. Parea tiene un carácter agrícola, con cultivos de cocos, vainilla y sandías. La economía se basa en la agricultura y el turismo. La población es de unos 200 habitantes. Históricamente, Parea fue un puerto importante para el comercio interinsular. La misión francesa erigió una iglesia en el siglo XIX. Parea tiene una escuela primaria y una oficina de correos. La laguna alberga una gran población de rayas. El turismo se centra en resorts ecológicos y eco-lodges. La cocina local es conocida por sus mariscos frescos. Anualmente se celebra un festival de la raya que rinde homenaje a la importancia de estos animales para la cultura local. Las caminatas por los bosques tropicales ofrecen vistas de la flora y fauna autóctonas.",
      pt: "Parea é uma aldeia na ilha de Huahine, na Polinésia Francesa, situada na costa norte. O assentamento é conhecido pela sua longa praia de areia branca e lagoa tranquila, ideal para nadar e navegar. Parea é de carácter agrícola, com cultivo de cocos, baunilha e melancias. A economia baseia-se na agricultura e no turismo. A população é de cerca de 200 habitantes. Historicamente, Parea foi um porto importante para o comércio interinsular. A missão francesa construiu uma igreja no século XIX. Parea tem uma escola primária e um posto de correios. A lagoa alberga uma grande população de raias. O turismo concentra-se em resorts ecológicos e eco-lodges. A gastronomia local é conhecida pelos seus mariscos frescos. Anualmente realiza-se um festival da raia, que homenageia a importância destes animais para a cultura local. Caminhadas pelas florestas tropicais oferecem vislumbres da flora e fauna locais.",
      fr: "Parea est un village situé sur l'île de Huahine en Polynésie française, sur la côte nord. La localité est réputée pour sa longue plage de sable blanc et son lagon paisible, idéal pour la baignade et la voile. Parea a une vocation agricole, avec la culture de la noix de coco, de la vanille et des pastèques. L'économie repose sur l'agriculture et le tourisme. La population est d'environ 200 habitants. Historiquement, Parea était un port important pour le commerce inter-insulaire. La mission française y a érigé une église au XIXe siècle. Parea possède une école primaire et un bureau de poste. Le lagon abrite une importante population de raies pastenagues. Le tourisme se concentre sur des complexes respectueux de l'environnement et des éco-lodges. La cuisine locale est célèbre pour ses fruits de mer frais. Chaque année se tient une fête de la raie, célébrant l'importance de ces animaux pour la culture locale. Des randonnées dans les forêts tropicales permettent d'observer la flore et la faune indigènes.",
    },
