      fr: ["La plage de Parea est longue de 2 km.", "Parea compte 210 habitants (chiffre 2017).", "L'église a été construite en 1852.", "Plus de 200 raies pastenagues vivent dans le lagon.", "La production de vanille est de 300 kg par an.", "La fête de la raie a lieu en septembre."],
