      hu: ["Egy jelentős helyi múzeum helyszíne", "Fafaragásairól és hagyományos tetoválásairól ismert", "Hozzáférés a 'Láthatatlan öbölhöz' (Baie Invisible)", "A sziget lótenyésztésének központja"],
      ro: ["Locația unui muzeu local important", "Cunoscut pentru sculpturile în lemn și tatuajele tradiționale", "Acces la 'Golful Invizibil' (Baie Invisible)", "Centru pentru creșterea cailor pe insulă"],
