    imageHint: "Vaipaee village valley Ua Huka Marquesas",
    descriptionAdvanced: {
      de: "Vaipaee ist der Hauptort der Insel Ua Huka in den Marquesas-Inseln und liegt am Ende einer spektakulären, tief eingeschnittenen Bucht, die als „Baie Invisible“ bekannt ist. Der Zugang vom Meer aus ist für Schiffe aufgrund der extrem schmalen Einfahrt zwischen steilen Klippen besonders schwierig, was dem Dorf eine geschützte und isolierte Lage verleiht. Vaipaee ist das kulturelle Herz der Insel und beherbergt ein bedeutendes Museum, das sich der Erhaltung der marquesanischen Traditionen widmet. Die Bewohner sind weltweit für ihre außergewöhnlichen Holzschnitzereien bekannt, die oft aus dem harten Holz des Miro-Baumes gefertigt werden. Ein weiteres besonderes Merkmal ist die Verbindung zur Pferdezucht; Ua Huka ist als „Insel der Pferde“ bekannt, und man sieht diese Tiere oft frei im grünen Tal grasen. Das Dorf bietet einen authentischen Einblick in das Leben in Polynesien, weitab der großen Touristenströme.",
      hu: "Vaipaee a marquises-szigeteki Ua Huka szigetének legnagyobb és legfontosabb települése, amely egy mély és keskeny völgy alján fekszik. A falu a „Láthatatlan öböl” (Baie Invisible) végén található, amely nevét onnan kapta, hogy a tenger felől érkező hajók számára szinte észrevehetetlen a magas sziklák közötti szűk bejárat. Vaipaee híres gazdag kulturális örökségéről, különösen a helyi múzeumról, ahol ősi fafaragásokat és hagyományos tetoválóművészeti emlékeket őriznek. A helyiek mesteri szinten űzik a fafaragást, alkotásaikat az egész Csendes-óceáni térségben nagyra értékelik. A völgyben és a környező dombokon számos ló kószál szabadon, mivel Ua Huka a lovairól is ismert Polinéziában. Az ide látogatók megtapasztalhatják a Marquesas-szigetek vadregényes tájait és a polinéz vendégszeretetet egy eldugott, érintetlen környezetben, ahol az idő lassabban jár.",
      ro: "Vaipaee este cel mai mare sat de pe insula Ua Huka din arhipelagul Marchize, fiind situat la capătul unei văi adânci și pitorești. Accesul către localitate se face prin „Golful Invizibil” (Baie Invisible), o intrare maritimă atât de îngustă și sinuoasă între stânci înalte încât este aproape nedetectabilă de pe oceanul deschis. Satul este centrul cultural al insulei, găzduind un muzeu important ce expune piese de artizanat tradițional, sculpturi antice și modele de tatuaje ancestrale. Comunitatea locală excelează în arta sculpturii în lemn de esență tare, produsele lor fiind căutate în toată Polinezia Franceză. Ua Huka este renumită și pentru populația sa de cai sălbatici, iar în Vaipaee aceștia pot fi văzuți adesea păscând liber pe versanții verzi ai văii. Localitatea oferă o incursiune autentică în stilul de viață marquesan, păstrând o legătură profundă cu natura și tradițiile polineziene.",
      en: "Vaipaee is the principal settlement on the island of Ua Huka within the Marquesas Islands, nestled at the base of a dramatic, narrow valley. It is famously situated at the end of the \"Invisible Bay\" (Baie Invisible), named for its narrow entrance between towering cliffs that makes it nearly impossible for sailors to spot from the open ocean. The village is the cultural anchor of the island, featuring a notable museum that houses traditional Marquesan artifacts, intricate wood carvings, and historical tattoo designs. The local artisans are highly skilled in carving miro wood, a tradition passed down through generations. Additionally, Ua Huka is known as the island of horses, and it is common to see these animals roaming freely through the lush valley of Vaipaee. This secluded village offers travelers an authentic glimpse into Polynesian life, characterized by a deep respect for ancestral traditions and a rugged, volcanic landscape of breathtaking beauty.",
      es: "Vaipaee es un asentamiento en la isla de Hiva Oa en las Islas Marquesas. El pueblo se sitúa en la costa sur y es conocido por sus sitios arqueológicos con petroglifos. Los aproximadamente 100 habitantes viven de la agricultura (fruta de pan, taro) y la pesca. Vaipaee fue anteriormente un importante centro comercial de sándalo. Las montañas circundantes ofrecen senderos hacia plataformas polinesias en ruinas (Marae). La iglesia de piedra de basalto es un punto destacado del lugar.",
      pt: "Vaipaee é uma povoação na ilha de Hiva Oa, nas Ilhas Marquesas. A aldeia situa-se na costa sul e é conhecida pelos seus sítios arqueológicos com petróglifos. Os cerca de 100 habitantes vivem da agricultura (fruta-pão, taro) e da pesca. Vaipaee foi anteriormente um importante centro de comércio de sândalo. As montanhas circundantes oferecem trilhos para caminhadas até plataformas polinésias em ruínas (Marae). A igreja de pedras de basalto é um ponto de destaque na localidade.",
      fr: "Vaipaee est un village de l'île d'Hiva Oa, dans les îles Marquises. Le village se situe sur la côte sud et est réputé pour ses sites archéologiques aux pétroglyphes. Les quelque 100 habitants vivent de l'agriculture (fruit à pain, taro) et de la pêche. Vaipaee était autrefois un comptoir important pour le bois de santal. Les montagnes environnantes offrent des sentiers menant à des plateformes polynésiennes en ruines (Marae). L'église en pierres de basalte est un point marquant du village.",
    },
