    imageHint: "Vaitahu monumental church Tahuata Marquesas",
    descriptionAdvanced: {
      de: "Vaitahu ist der größte Ort auf der Insel Tahuata und blickt auf eine bewegte koloniale Geschichte zurück. Hier fand im Jahr 1842 die erste formelle Annexion Französisch-Polynesiens durch Admiral Dupetit-Thouars statt, was das Dorf zu einem historisch bedeutsamen Ort macht. Ein architektonisches Highlight ist die katholische Kirche Notre-Dame de Vaitahu, die für ihre monumentale Bauweise und die feinen polynesischen Schnitzereien bekannt ist, die biblische Motive mit lokaler Symbolik verbinden. Vaitahu gilt zudem als Zentrum der Handwerkskunst auf den Marquesas-Inseln, insbesondere für die filigrane Schnitzerei aus Rinderknochen, die von den lokalen Künstlern mit großer Meisterschaft ausgeführt wird. Das Dorf liegt geschützt in einer tiefen Bucht an der Westküste und bietet einen authentischen Einblick in das ruhige Leben des Archipels. Besucher finden hier eine Atmosphäre der Abgeschiedenheit, geprägt von der Gastfreundschaft der Bewohner und der üppigen tropischen Vegetation der Umgebung.",
      hu: "Vaitahu Tahuata szigetének közigazgatási és kulturális központja, amely jelentős történelmi múlttal rendelkezik. Ez a település volt a helyszíne 1842-ben Francia Polinézia első hivatalos annexiójának, amikor Dupetit-Thouars admirális partra szállt itt. A falu legimpozánsabb épülete a Notre-Dame de Vaitahu katolikus templom, amely hatalmas méreteivel és különleges belső díszítésével hívja fel magára a figyelmet; a belső térben polinéz motívumokkal ötvözött keresztény szimbólumokat láthatunk. Vaitahu híres a Marquesas-szigeteken belüli kézművességéről is, különösen a finom csontfaragásról, amelynek mesterfogásait nemzedékről nemzedékre örökítik. A sziget nyugati partján, egy védett öbölben fekvő település megőrizte tradicionális jellegét, ahol a látogatók közvetlen közelről ismerhetik meg a polinéz mindennapokat, távol a tömegturizmustól, buja trópusi környezetben.",
      ro: "Vaitahu este principala localitate de pe insula Tahuata, fiind un loc cu o încărcătură istorică deosebită pentru Polinezia Franceză. În anul 1842, acest sat a fost martorul primei anexări formale a arhipelagului de către amiralul Dupetit-Thouars, marcând începutul erei coloniale franceze. Punctul de reper cel mai important este biserica Notre-Dame de Vaitahu, o construcție monumentală ce îmbină arhitectura europeană cu motivele decorative polineziene, reflectând sincretismul cultural local. Satul este renumit în toate Insulele Marquesas pentru măiestria artizanilor săi în sculptura fină în os de vită, obiectele create aici fiind foarte apreciate de colecționari. Situat într-un golf adăpostit pe coasta de vest, Vaitahu oferă o atmosferă liniștită, unde viața se desfășoară într-un ritm tradițional. Vegetația tropicală luxuriantă și munții abrupți care încadrează golful completează tabloul unui așezări autentice și izolate.",
      en: "Vaitahu is the administrative and cultural heart of Tahuata island, holding a significant place in the history of French Polynesia. In 1842, it was the site of the first formal annexation of the archipelago by France under Admiral Dupetit-Thouars. The village's skyline is dominated by the monumental Church of Notre-Dame de Vaitahu, renowned for its impressive architecture and intricate Polynesian carvings that decorate its interior, blending Catholic tradition with Marquesan identity. Vaitahu is also celebrated as a premier center for craftsmanship, particularly the meticulous art of bone carving, where local artisans transform cattle bone into exquisite jewelry and decorative pieces. Located on a sheltered western bay, the village maintains a peaceful and traditional way of life, untouched by large-scale tourism. Visitors can experience authentic Marquesan hospitality while surrounded by lush tropical landscapes and the towering emerald cliffs that protect the harbor.",
      es: "Vaitahu es un pueblo en la isla de Tahuata, en las Marquesas. Se encuentra en la costa sur y fue el primer lugar que los españoles pisaron en las Marquesas en 1595. Sus aproximadamente 200 habitantes viven del cultivo de vainilla y la pesca. El lugar tiene una iglesia católica del siglo XIX con tallas de madera. En la bahía de Vaitahu anclan ocasionalmente cruceros. El entorno se caracteriza por acantilados escarpados y valles verdes.",
      pt: "Vaitahu é uma aldeia na ilha de Tahuata, nas Marquesas. Situa-se na costa sul e foi o primeiro local onde os espanhóis desembarcaram nas Marquesas em 1595. Os cerca de 200 habitantes vivem do cultivo de baunilha e da pesca. A localidade possui uma igreja católica do século XIX com entalhes em madeira. Na baía de Vaitahu ancoram ocasionalmente navios de cruzeiro. A envolvente é marcada por falésias íngremes e vales verdes.",
      fr: "Vaitahu est un village de l'île de Tahuata dans les Marquises. Il est situé sur la côte sud et fut le premier endroit où les Espagnols mirent le pied aux Marquises en 1595. Les quelque 200 habitants vivent de la culture de la vanille et de la pêche. Le village possède une église catholique du XIXe siècle avec des sculptures sur bois. Des bateaux de croisière jettent parfois l'ancre dans la baie de Vaitahu. Les environs sont caractérisés par des falaises escarpées et des vallées verdoyantes.",
    },
