      pt: ["População de Vaitahu: aprox. 200 (estimativa de 2020)", "Primeiro avistamento por europeus: 1595 (expedição espanhola sob Mendaña)", "Área de plantações de baunilha: 15 hectares", "Altura das falésias na costa: até 300 m", "Número anual de visitantes: aprox. 500 (turistas de cruzeiros)", "Distância até à ilha vizinha Hiva Oa: 4 km"],
