    imageHint: "Hurepiti bay and vanilla plantations Taha'a",
    descriptionAdvanced: {
      de: "Hurepiti ist ein malerisches Dorf an der geschützten Westküste von Taha'a, der Insel, die weltweit für ihre erstklassige Vanille bekannt ist. Das Dorf liegt tief in der gleichnamigen Bucht, die ein beliebter Ankerplatz für Segler ist und einen direkten Blick auf die Silhouette der Nachbarinsel Bora Bora bietet. Hurepiti hat sich zu einem Zentrum für Ökotourismus entwickelt, insbesondere durch botanische Touren, bei denen Besucher die komplexen Prozesse des Vanilleanbaus und die reiche tropische Flora kennenlernen können. Die Bewohner leben nach wie vor überwiegend von der Landwirtschaft, wobei neben Vanille auch Kopra und verschiedene exotische Früchte produziert werden. Die Atmosphäre im Dorf ist geprägt von traditioneller polynesischer Gastfreundschaft und einem langsamen Lebensrhythmus. Eine Entdeckungstour durch Hurepiti führt vorbei an gepflegten Gärten und kleinen Familienbetrieben, die das authentische Erbe der Gesellschaftsinseln bewahren und einen Kontrast zu den touristisch stärker erschlossenen Nachbarinseln bilden.",
      hu: "Hurepiti egy varázslatos falu Taha'a nyugati partján, amely mélyen benyúlik a sziget egyik legvédettebb öblébe. A település világszerte ismert a prémium minőségű vaníliájáról, és számos helyi család foglalkozik itt a \"fekete arany\" termesztésével és feldolgozásával. Hurepiti nemcsak a mezőgazdaságáról, hanem botanikai túráiról is híres, ahol a látogatók szakértő vezetők segítségével ismerhetik meg a polinéz növényvilág titkait és a gyógynövények használatát. Az öböl vize kristálytiszta, és gyakran horgonyoznak itt vitorlások, mivel a helyszín tökéletes rálátást biztosít a horizonton magasodó Bora Bora szigetére. A falu lakói hűen őrzik hagyományaikat, a mindennapokat a koprakészítés és a halászat ritmusa határozza meg. Az ökoturizmus iránt érdeklődők számára Hurepiti az egyik legjobb hely Taha'a szigetén, hogy közvetlen tapasztalatot szerezzenek a fenntartható gazdálkodásról és a polinéz kultúra mély tiszteletéről a természet iránt.",
      ro: "Hurepiti este un sat pitoresc situat pe coasta de vest a insulei Taha'a, într-un golf adânc care oferă adăpost natural ambarcațiunilor ce navighează în Polinezia Franceză. Localitatea este renumită pentru fermele sale de vanilie, Taha'a fiind cunoscută drept \"Insula Vaniliei\", unde vizitatorii pot învăța despre procesul meticulos de polenizare manuală a orhideelor de vanilie. Hurepiti a devenit un centru de excelență pentru ecoturism, oferind tururi botanice ghidate care explorează biodiversitatea luxuriantă a văilor din jur. De pe malul golfului, se poate admira o panoramă superbă către insula vecină Bora Bora, situată chiar vizavi. Viața în Hurepiti decurge într-un ritm relaxat, marcat de activități agricole tradiționale și de producția de copra. Comunitatea locală este mândră de moștenirea sa culturală, păstrând grădini spectaculoase pline de flori tropicale și fructe exotice. Pentru călătorul dornic de autenticitate, Hurepiti reprezintă esența spiritului polinezian, departe de aglomerația marilor complexe hoteliere.",
      en: "Hurepiti is a charming village located on the sheltered western coast of Taha'a, an island celebrated globally as the \"Vanilla Island.\" Nestled at the head of a deep, tranquil bay, the village serves as a prime anchorage for yachts and offers stunning views across the water to the silhouette of Bora Bora. Hurepiti has gained a reputation as a center for eco-tourism and botanical exploration, with local guides leading immersive tours that showcase the intricate process of vanilla cultivation and the island's medicinal plant lore. The community's lifestyle is deeply intertwined with the land, focusing on traditional agriculture, copra production, and pearl farming. Walking through the village, visitors can experience the authentic Polynesian \"joie de vivre\" amidst lush gardens filled with hibiscus and tiare flowers. Hurepiti remains a place where traditional values are cherished, providing a peaceful retreat for those who wish to discover the true heart of the Society Islands through sustainable tourism and direct contact with the welcoming local population.",
      es: "Hurepiti es un pueblo en la isla de Taha'a en la Polinesia Francesa, situado en la costa norte. El asentamiento es conocido por sus plantaciones de vainilla y la producción de copra. Los aproximadamente 150 habitantes viven principalmente de la agricultura. En Hurepiti hay una pequeña iglesia con un retablo pintado. El lugar está rodeado de plantaciones de cocoteros. La bahía de Hurepiti es tranquila y es utilizada por los lugareños para pescar.",
      pt: "Hurepiti é uma aldeia na ilha de Taha'a, na Polinésia Francesa, situada na costa norte. O assentamento é conhecido pelas suas plantações de baunilha e produção de copra. Os cerca de 150 habitantes vivem principalmente da agricultura. Em Hurepiti existe uma pequena igreja com um retábulo pintado. O local é cercado por plantações de coqueiros. A baía de Hurepiti é tranquila e utilizada pelos habitantes locais para a pesca.",
      fr: "Hurepiti est un village de l'île de Taha'a, en Polynésie française, situé sur la côte nord. La localité est connue pour ses vanilleraies et sa production de coprah. Les quelque 150 habitants vivent principalement de l'agriculture. Hurepiti abrite une petite église au retable peint. Le village est entouré de cocoteraies. La baie de Hurepiti est paisible et fréquentée par les pêcheurs locaux.",
    },
