    imageHint: "Hipu village Taha'a coconut palms",
    descriptionAdvanced: {
      de: "Hipu ist ein charmantes Dorf an der Nordküste der Insel Taha'a, die oft als die 'Vanilleinsel' Französisch-Polynesiens bezeichnet wird. Inmitten einer üppigen tropischen Vegetation gelegen, bewahrt Hipu die authentische Ruhe des polynesischen Insellebens, weit weg von den großen Touristenströmen. Die Bewohner widmen sich traditionell dem Anbau von Vanille und Kokosnüssen, wobei die Kopra-Gewinnung eine wichtige Einnahmequelle darstellt. Eine Besonderheit des Dorfes ist die kleine, farbenfroh gestaltete Gemeinschaftskirche, die ein beliebtes Fotomotiv darstellt. Hipu ist zudem für sein traditionelles Kunsthandwerk bekannt, insbesondere für die Herstellung kunstvoll geflochtener Körbe aus Pandanusblättern. Von der Küste aus bietet sich ein herrlicher Blick auf die türkisfarbene Lagune, die Taha'a mit der Nachbarinsel Raiatea teilt. Besucher schätzen das Dorf für seine herzliche Gastfreundschaft und die Möglichkeit, den langsamen Rhythmus des Lebens im Südpazifik kennenzulernen, während der Duft von Vanille in der warmen Luft liegt.",
      hu: "Hipu egy elbűvölő kis település Taha'a szigetének északi partján, amely Francia Polinézia egyik legérintetlenebb pontja. A falut sűrű trópusi növényzet, kókuszpálmák és kiterjedt vaníliaültetvények ölelik körül, hiszen Taha'a híres a világ egyik legjobb minőségű vaníliájáról. Hipu lakói a mai napig őrzik hagyományos életmódjukat; a kopra készítése és a vanília kézi beporzása a mindennapok része. A település egyik legfőbb nevezetessége a helyi kézművesség, különösen a pandanuszlevelekből font kosarak és szőnyegek, amelyek híresek tartósságukról és díszes mintáikról. A falu központjában álló kis templom élénk színeivel a közösségi élet központja. A part mentén sétálva lenyűgöző kilátás nyílik a türkizkék lagúnára, ahol a kristálytiszta víz és a környező motuk (korallszigetek) látványa fogadja az érkezőt. Hipu tökéletes célpont azoknak, akik a valódi polinéz vendégszeretetet és a természet közelségét keresik, távol a luxusüdülők zajától.",
      ro: "Hipu este un sat pitoresc situat pe coasta de nord a insulei Taha'a, în Polinezia Franceză, un loc unde tradiția și natura se împletesc armonios. Cunoscută sub numele de 'Insula Vaniliei', Taha'a își găsește în Hipu un reprezentant autentic, localnicii ocupându-se aici cu cultivarea prețioaselor păstăi și cu producția de copră din nucile de cocos abundente. Satul este renumit în arhipelag pentru măiestria artizanilor săi în împletirea coșurilor din frunze de pandanus, o îndeletnicire transmisă din generație în generație. Un punct de interes vizual este mică biserică a comunității, vopsită în culori pastelate, care oferă un contrast superb cu verdele crud al vegetației tropicale. Hipu oferă o perspectivă rară asupra ritmului lent al vieții insulare, unde sunetul oceanului și aroma de vanilie definesc atmosfera. De pe țărmul satului, se pot admira apele limpezi ale lagunei comune cu insula Raiatea, fiind un punct ideal pentru a observa ecosistemul marin fragil și bogat al Pacificului de Sud.",
      en: "Hipu is a charming coastal village located on the northern shore of Taha'a, an island celebrated in French Polynesia as the 'Vanilla Island.' Nestled between lush green mountains and the crystal-clear lagoon, Hipu offers a glimpse into a traditional Polynesian way of life that remains largely untouched by mass tourism. The local economy is driven by the cultivation of high-quality vanilla and the production of copra from the surrounding coconut groves. The village is particularly famous for its skilled artisans who specialize in traditional basket weaving using pandanus leaves. A notable landmark is the small, brightly colored community church, which serves as a gathering place for the village's friendly inhabitants. Travelers visiting Hipu can enjoy the serene atmosphere, explore the nearby vanilla plantations, and take in the stunning views of the turquoise waters and distant motus. It is an ideal spot for those seeking authenticity and natural beauty in the heart of the Society Islands.",
      es: "Hipu es un pueblo de la isla de Taha'a (denominación alternativa Haamene). Se encuentra en la costa este y es conocido por sus granjas de perlas. Los aproximadamente 180 habitantes viven del cultivo de perlas negras y de la agricultura. Hipu tiene un pequeño muelle para barcos. El entorno está caracterizado por un denso bosque tropical. El lugar ofrece vistas a la isla vecina de Raiatea.",
      pt: "Hipu é uma aldeia na ilha de Taha'a (denominação alternativa Haamene). Localiza-se na costa leste e é conhecida pelas suas fazendas de pérolas. Os cerca de 180 habitantes vivem do cultivo de pérolas negras e da agricultura. Hipu tem um pequeno ancoradouro para barcos. O entorno é caracterizado por uma densa floresta tropical. O local oferece uma vista da ilha vizinha de Raiatea.",
      fr: "Hipu est un village sur l'île de Taha'a (autre dénomination Haamene). Il est situé sur la côte est et est réputé pour ses fermes perlières. Les quelque 180 habitants vivent de la culture des perles noires et de l'agriculture. Hipu dispose d'un petit débarcadère pour les bateaux. Les environs sont marqués par une forêt tropicale dense. La localité offre une vue sur l'île voisine de Raiatea.",
    },
