    imageHint: "Tiva village Taha'a sunset with Bora Bora",
    descriptionAdvanced: {
      de: "Tiva ist ein malerisches Dorf an der Westküste von Taha'a, das tief in der traditionellen polynesischen Kultur verwurzelt ist. Bekannt als ein bedeutendes Zentrum für hochwertige schwarze Perlen, beherbergt das Dorf mehrere renommierte Perlenfarmen, in denen Besucher den faszinierenden Prozess der Perlenzucht von der Einpflanzung bis zur Ernte miterleben können. Die Lage des Dorfes bietet einen der spektakulärsten Ausblicke in Französisch-Polynesien: Bei Sonnenuntergang zeichnet sich die markante Silhouette der Nachbarinsel Bora Bora deutlich am Horizont ab. Tiva ist ein beliebter Stopp für Lagunentouren, bei denen Reisende die blühenden Gärten und die mit tropischen Blumen geschmückten Wege des Ortes bewundern können. Die Bewohner sind für ihre Gastfreundschaft und ihre enge Verbindung zum Meer bekannt, was sich im entspannten Lebensrhythmus widerspiegelt. Hier findet man die authentische Atmosphäre der Gesellschaftsinseln, fernab vom Massentourismus, geprägt vom Duft der Vanille und dem Glanz der kostbaren Perlen.",
      hu: "Tiva egy festői falu Taha'a nyugati partján, amely a hagyományos polinéz életmód és a tengeri gazdálkodás egyik legfontosabb központja. A település elsősorban kiváló minőségű gyöngytenyésztéséről híres; a környéken működő gyöngyfarmok látogatása során a vendégek megismerhetik a híres fekete gyöngyök születésének minden részletét. Tiva földrajzi fekvése különleges élményt kínál: a falu partjairól nézve naplementekor Bora Bora ikonikus sziluettje rajzolódik ki a horizonton, felejthetetlen látványt nyújtva a látogatóknak. A falu a lagúnatúrák egyik kedvelt megállója, ahol a vendégeket trópusi virágokkal teli kertek és barátságos helyiek fogadják. A település megőrizte autentikus jellegét, ahol a mindennapokat a halászat és a vanília-termesztés határozza meg, miközben a levegőben az édes illatok keverednek a tenger sós párájával. Tiva tökéletes helyszín azok számára, akik Francia Polinézia békésebb, érintetlenebb arcát szeretnék felfedezni, ahol a természet és a hagyomány harmóniában él együtt.",
      ro: "Tiva este un sat pitoresc situat pe coasta de vest a insulei Taha'a, reprezentând esența stilului de viață polinezian tradițional. Renumit ca un centru important pentru cultura perlelor negre de înaltă calitate, satul găzduiește numeroase ferme de perle unde vizitatorii pot învăța despre procesul meticulos de cultivare al acestor nestemate marine. Poziția sa geografică oferă un avantaj vizual spectaculos: de pe țărmul satului, silueta inconfundabilă a insulei Bora Bora se profilează clar la orizont, oferind unele dintre cele mai frumoase apusuri de soare din Polinezia Franceză. Tiva este o oprire esențială în tururile lagunare, fiind apreciat pentru străzile sale pline de flori și grădinile luxuriante care reflectă grija localnicilor pentru pământul lor. Atmosfera este una de liniște profundă, unde ritmul vieții este dictat de mare și de tradițiile ancestrale ale Insulelor Societății. Este locul ideal pentru a descoperi ospitalitatea autentică și frumusețea naturală a Pacificului de Sud, departe de zonele turistice aglomerate, într-un decor dominat de arome de vanilie.",
      en: "Tiva is a picturesque village nestled on the western coast of Taha'a, embodying the serene and traditional spirit of French Polynesia. It has gained regional recognition as a hub for high-quality pearl cultivation, with several family-run pearl farms offering guided tours that detail the delicate process of producing the famous Tahitian black pearl from grafting to harvest. One of the village's most defining features is its strategic vantage point, providing breathtaking views of Bora Bora’s dramatic silhouette across the lagoon, especially during the golden hour. Tiva is a quintessential stop for lagoon excursions, where travelers are greeted by lush tropical gardens and paths adorned with native hibiscus and frangipani flowers. The local community remains deeply connected to maritime traditions and sustainable vanilla farming, maintaining an authentic atmosphere that feels worlds away from large-scale resorts. Here, the fragrant scent of vanilla from nearby plantations mingles with the sea breeze, offering a truly immersive sensory experience of life in the Society Islands.",
      es: "Tiva es un pequeño pueblo en la isla de Taha'a en la Polinesia Francesa, situado en la costa sur. El asentamiento está rodeado de plantaciones de frutas. Los aproximadamente 100 habitantes viven de la agricultura y la pesca. Tiva tiene una pequeña capilla y una plaza comunitaria. La costa consta de playas de lava negra. Cerca se encuentran antiguas estructuras de piedra polinesias.",
      pt: "Tiva é uma pequena aldeia na ilha de Taha'a, na Polinésia Francesa, situada na costa sul. A povoação está rodeada por plantações de fruta. Os cerca de 100 habitantes vivem da agricultura e da pesca. Tiva tem uma pequena capela e uma praça comunitária. A costa é composta por praias de lava negra. Nas proximidades encontram-se antigas estruturas de pedra polinésias.",
      fr: "Tiva est un petit village sur l'île de Taha'a en Polynésie française, situé sur la côte sud. Le village est entouré de vergers. Les quelque 100 habitants vivent de l'agriculture et de la pêche. Tiva possède une petite chapelle et une place commune. La côte est composée de plages de lave noire. Des structures anciennes en pierre polynésienne se trouvent à proximité.",
    },
