      fr: ["Nombre d'habitants de Tiva : env. 100 (estimation 2020)", "Superficie des vergers : 20 hectares", "Longueur de la plage de sable noir : 500 m", "Nombre de structures en pierre conservées : 3", "Distance de la localité la plus proche (Patio) : 5 km", "Humidité moyenne : 80%"],
