      hu: ["A vanília és kopra exportjának fő kikötője", "A vitorlázók fontos ellátóhelye", "Helyi rumlepárlója van", "Közvetlen hozzáférést biztosít gyönyörű motukhoz"],
      ro: ["Portul principal pentru exportul de vanilie și copra", "Popas important de aprovizionare pentru navigatori", "Deține o distilerie locală de rom", "Oferă acces direct la motu-uri superbe"],
