    imageHint: "Tapuamu harbor and rum distillery Taha'a",
    descriptionAdvanced: {
      de: "Tapuamu ist der strategisch wichtigste Hafenort auf der Insel Taha'a in Französisch-Polynesien. Er fungiert als zentraler Handelsplatz für die landwirtschaftlichen Erzeugnisse der Insel, insbesondere für die weltberühmte Vanille und Kopra, die von hier aus exportiert werden. Für Segler und Weltumsegler ist Tapuamu eine unverzichtbare Versorgungsstation, da der Ort geschützte Anlegestellen und wichtige Dienstleistungen bietet. Eine besondere Attraktion ist die lokale Rum-Destillerie, in der Besucher den aus lokalem Zuckerrohr hergestellten Rum probieren und kaufen können. Von der Bucht aus hat man zudem einen direkten Zugang zu einigen der schönsten Motus (kleinen Koralleninseln) der Region, die ideale Bedingungen zum Schnorcheln im kristallklaren Wasser bieten. Tapuamu bewahrt trotz seiner wirtschaftlichen Bedeutung eine entspannte, polynesische Atmosphäre, in der das Leben noch dem Rhythmus der Gezeiten und Ernten folgt.",
      hu: "Tapuamu Taha'a szigetének legfontosabb kikötővárosa és kereskedelmi központja Francia Polinéziában. A település kulcsszerepet játszik a sziget gazdaságában, innen indul útjára a világhírű taha'ai vanília és a kopra a nemzetközi piacok felé. A vitorlázók körében Tapuamu népszerű megállóhely, mivel kiváló ellátó állomásként szolgál, ahol friss élelmiszert és üzemanyagot vételezhetnek. A város egyik fő nevezetessége a helyi rumlepárló, ahol a látogatók megismerhetik a cukornád feldolgozásának folyamatát és megkóstolhatják a sziget különleges párlatait. A kikötőből könnyen elérhetőek a környező lagúna apró szigetei, a motuk, amelyek fehér homokos partjaikkal és gazdag víz alatti élővilágukkal várják a kirándulókat. Tapuamu az a hely, ahol a modern logisztika találkozik a hagyományos polinéz vendégszeretettel és a trópusi természet nyugalmával.",
      ro: "Tapuamu este principalul oraș-port de pe insula Taha'a, jucând rolul de centru vital pentru comerțul și aprovizionarea Polineziei Franceze. Portul este punctul central pentru exportul celor mai prețioase produse locale: vanilia aromată de Taha'a și copra, care susțin economia insulară. Pentru navigatorii care explorează Pacificul, Tapuamu reprezintă o oprire esențială pentru realimentare și logistică, oferind facilități portuare sigure. O atracție deosebită în oraș este distileria locală de rom, unde se produce băutura tradițională din trestie de zahăr cultivată pe insulă. Dincolo de activitatea comercială, Tapuamu este poarta de acces către lagunele spectaculoase și motu-urile din jur, oferind vizitatorilor posibilitatea de a explora bariera de corali în condiții ideale. Satul păstrează un ritm de viață liniștit, reflectând cultura autentică polineziană, unde ospitalitatea localnicilor completează frumusețea peisajului tropical.",
      en: "Tapuamu serves as the primary gateway and commercial hub of Taha'a, an island in French Polynesia renowned for its lush landscapes and agricultural bounty. The town's port is the central shipping point for the island's world-famous vanilla and copra, making it the heartbeat of the local economy. For the sailing community, Tapuamu is a strategic supply stop, offering essential services, fuel, and provisions in a well-protected bay. Visitors are often drawn to the local rum distillery, where they can witness the production of artisanal spirits crafted from island-grown sugarcane. The port also provides immediate access to the surrounding lagoon and its pristine motus—small coral islets—which are perfect for day trips and snorkeling adventures. Combining functional importance with a laid-back island atmosphere, Tapuamu is a quintessential Polynesian port town where tradition and commerce meet.",
      es: "Tapuamu es un asentamiento en la isla de Taha'a, situado en la costa oeste. El pueblo está rodeado de campos de vainilla y plantaciones de cocoteros. Los aproximadamente 120 habitantes viven principalmente de la agricultura. En Tapuamu hay una pequeña iglesia protestante. El lugar es tranquilo y remoto. La laguna frente a la costa es rica en vida marina. Todavía se utilizan canoas tradicionales para la pesca.",
      pt: "Tapuamu é um povoado na ilha de Taha'a, localizado na costa oeste. A aldeia está rodeada por campos de baunilha e plantações de coqueiros. Os cerca de 120 habitantes vivem principalmente da agricultura. Em Tapuamu existe uma pequena igreja protestante. O local é calmo e isolado. A lagoa em frente à costa é rica em vida marinha. Canoas tradicionais ainda são usadas para a pesca.",
      fr: "Tapuamu est un établissement sur l'île de Taha'a, situé sur la côte ouest. Le village est entouré de champs de vanille et de cocoteraies. Les quelque 120 habitants vivent principalement de l'agriculture. Tapuamu possède une petite église protestante. L'endroit est calme et reculé. Le lagon au large est riche en vie marine. Des pirogues traditionnelles sont encore utilisées pour la pêche.",
    },
