      hu: ["Tapuamu lakossága: kb. 120 fő (2020-as becslés)", "Vaníliaföldek száma: 12", "Éves kopratermelés: 15 tonna", "Protestáns templom alapításának éve: 1901", "Lagúna területe: 2 km²", "Lagúna átlagos mélysége: 5 m"],
