    imageHint: "Haapu bay and village Huahine",
    descriptionAdvanced: {
      de: "Haapu ist ein ruhiges und abgelegenes Fischerdorf im Südwesten von Huahine Iti, der kleineren der beiden Zwillingsinseln von Huahine. Das Dorf liegt am Ende einer tiefen, fjordähnlichen Bucht, die von steilen, grün bewachsenen Bergen umgeben ist, was Haapu eine fast mystische Atmosphäre verleiht. Die Region ist bekannt für ihre Perlenzucht; in der Bucht von Haapu befinden sich einige der besten Farmen für die begehrten schwarzen Tahiti-Perlen. Die Bewohner von Haapu führen ein traditionelles Leben, das stark von der Fischerei und dem Anbau von Kokosnüssen geprägt ist. Da Huahine weniger touristisch erschlossen ist als Tahiti oder Bora Bora, bietet Haapu einen unverfälschten Einblick in die polynesische Kultur. Die üppigen Kokosnuss- und Bananenhaine, die das Dorf umgeben, zeugen von der fruchtbaren vulkanischen Erde. Besucher schätzen Haapu vor allem für seine Stille, die klaren Gewässer zum Schnorcheln und die herzliche Aufnahme durch die lokale Gemeinschaft, die stolz auf ihre isolierte Lage und ihre Unabhängigkeit ist.",
      hu: "Haapu egy festői halászfalu Huahine Iti nyugati partján, egy mély és védett öböl mélyén. A település híres a nyugalmáról és elszigeteltségéről, mivel távol esik a sziget főbb turistaútvonalaitól, így megőrizte hamisítatlan polinéz jellegét. Az öböl vize kiválóan alkalmas gyöngytenyésztésre, és a látogatók gyakran megtekinthetik a tengerbe telepített gyöngyfarmokat, ahol a híres fekete igazgyöngyöket tenyésztik. Haaput meredek, sűrű trópusi erdővel borított hegyek veszik körül, a falut pedig kókuszligetek és banánültetvények szegélyezik. A lakók főként halászatból és mezőgazdaságból élnek, a mindennapokat a közösségi élet és a hagyományos kézművesség határozza meg. Az ide látogatók számára Haapu tökéletes hely a kikapcsolódásra, a búvárkodásra a kristálytiszta lagúnában, vagy egy túrára a környező hegyekbe. A falu vendégszeretetéről és a polinéz vendéglátás őszinteségéről ismert, amely Huahine szigetének egyik legfőbb vonzereje.",
      ro: "Haapu este un mic sat de pescari situat pe coasta de vest a Huahine Iti, într-un golf adânc și spectaculos care pătrunde adânc în inima insulei. Înconjurat de munți abrupți acoperiți de o vegetație tropicală luxuriantă și de livezi întinse de cocos, Haapu oferă unul dintre cele mai pitorești peisaje din Polinezia Franceză. Satul este o locație cheie pentru cultura perlelor negre, apele liniștite ale golfului fiind ideale pentru fermele marine de perle care pot fi vizitate de turiști. Comunitatea din Haapu păstrează un mod de viață tradițional, unde pescuitul și agricultura de subzistență sunt activitățile principale. Izolarea relativă a satului a permis conservarea autenticității culturale, făcându-l o destinație preferată pentru cei care caută liniște și o conexiune reală cu natura. Golful Haapu este, de asemenea, un loc excelent pentru navigație și snorkeling, apele sale fiind pline de viață marină colorată. Pentru vizitatori, Haapu reprezintă un refugiu seren, unde ospitalitatea polineziană se îmbină perfect cu frumusețea sălbatică a peisajului vulcanic.",
      en: "Haapu is a secluded fishing village situated on the western shore of Huahine Iti, the smaller of the two islands that form Huahine. Located at the base of a deep, emerald bay and surrounded by verdant mountains and vast coconut groves, the village is one of the island's most peaceful enclaves. Haapu is renowned for its black pearl farming, with several farms located in the sheltered waters of the bay where visitors can learn about the delicate process of pearl grafting. The residents of Haapu maintain a traditional Polynesian lifestyle, largely centered around artisanal fishing and small-scale agriculture, such as taro and banana cultivation. Because Huahine is known as the \"Garden Island\" for its wild and untamed beauty, Haapu perfectly reflects this reputation with its lush, undisturbed surroundings. For travelers seeking a break from the more commercialized islands, Haapu offers a serene atmosphere, crystal-clear lagoon waters ideal for exploring by kayak, and a chance to experience the genuine warmth and slow-paced rhythm of a traditional Society Islands community.",
      es: "Haapu es un pueblo en la isla de Taha'a, situado en la costa este. El asentamiento es conocido por sus casas tradicionales polinesias. Los aproximadamente 130 habitantes viven de la agricultura y la pesca. En Haapu hay una escuela primaria y una tienda pequeña. El entorno es verde y montañoso. La laguna es ideal para el esnórquel. La comunidad está muy unida.",
      pt: "Haapu é uma aldeia na ilha de Taha'a, localizada na costa leste. O povoado é conhecido pelas suas casas tradicionais polinésias. Os cerca de 130 habitantes vivem da agricultura e da pesca. Em Haapu existe uma escola primária e uma pequena loja. O entorno é verde e montanhoso. A lagoa é ideal para snorkeling. A comunidade é muito unida.",
      fr: "Haapu est un village sur l'île de Taha'a, situé sur la côte est. La localité est connue pour ses maisons traditionnelles polynésiennes. Les quelque 130 habitants vivent de l'agriculture et de la pêche. Haapu dispose d'une école primaire et d'un petit magasin. Les environs sont verdoyants et vallonnés. Le lagon est idéal pour le snorkeling. La communauté y est très soudée.",
    },
