    imageHint: "Blue-eyed sacred eels in Faie Huahine",
    descriptionAdvanced: {
      de: "Das idyllische Dorf Faie liegt an der Ostküste von Huahine Nui und ist tief in der polynesischen Mythologie verwurzelt. Bekanntheit erlangte der Ort vor allem durch seine heiligen, blauäugigen Aale, die im kristallklaren Wasser des Dorfbachs leben. Diese imposanten Kreaturen gelten als Boten der Götter und werden von den Einheimischen respektvoll mit Makrelen gefüttert, was Besuchern oft spektakuläre Einblicke ermöglicht. Über dem Dorf erhebt sich der Weg zum Belvedere-Aussichtspunkt, von dem aus man einen atemberaubenden Blick über die Buchten von Maroe und Faie genießt. Die Atmosphäre im Dorf ist ruhig und authentisch, fernab des Massentourismus. Hier kann man das traditionelle Leben der Inselbewohner beobachten, die oft noch vom Fischfang und dem Anbau von Vanille leben. Faie ist ein Ort, an dem Legenden lebendig bleiben und die Verbindung zwischen Mensch und Natur auf eine spirituelle Weise spürbar wird.",
      hu: "Faie egy varázslatos kis falu Huahine Nui keleti partján, amely mélyen gyökerezik a polinéz mitológiában és hagyományokban. A település legfőbb nevezetessége a falu patakjában élő szent, kék szemű angolnák csoportja. Ezeket a hatalmas, szelíd állatokat a helyiek az istenek hírnökeinek tekintik, és rendszeresen etetik őket, amit a látogatók is megcsodálhatnak. A falu felett magasodik a Belvedere kilátóhoz vezető út, ahonnan páratlan panoráma nyílik a Maroe-öbölre és a környező türkizkék lagúnákra. Faie hangulata csendes és autentikus, megőrizve a szigetek régi báját, ahol az idő mintha lassabban telne. A lakosok büszkék kulturális örökségükre, és szívesen mesélnek a helyi legendákról a betérőknek. A falu ideális megálló azok számára, akik szeretnék megismerni Huahine spirituális oldalát és élvezni a buja trópusi környezet nyugalmát.",
      ro: "Satul idilic Faie este situat pe coasta de est a insulei Huahine Nui și este profund înrădăcinat în mitologia polineziană. Localitatea a devenit faimoasă în special datorită anghilelor sale sacre cu ochi albaștri, care trăiesc în apele limpezi ale pârâului ce traversează satul. Aceste creaturi impunătoare sunt considerate mesageri ai zeilor, iar localnicii le hrănesc cu respect, oferind vizitatorilor ocazia de a le vedea de aproape. Deasupra satului pornește drumul către punctul de belvedere Belvedere, de unde se deschide o vedere panoramică spectaculoasă asupra golfului Maroe și a peisajului înconjurător. Atmosfera din sat este una liniștită și autentică, departe de agitația turismului de masă. Aici, tradițiile sunt păstrate cu sfințenie, iar viața se desfășoară într-un ritm domol, legat de mare și de pământ. Faie este un loc unde legendele prind viață, iar legătura dintre om și natură este percepută la un nivel spiritual profund.",
      en: "The idyllic village of Faie is nestled on the eastern coast of Huahine Nui, a place deeply rooted in Polynesian mythology and local traditions. The village is most famous for its sacred blue-eyed eels that inhabit the crystal-clear waters of the local stream. These impressive creatures are regarded as messengers of the gods, and locals respectfully feed them by hand, providing a fascinating sight for visitors. Rising above the village is the trail leading to the Belvedere lookout, which offers one of the most breathtaking panoramic views over Maroe Bay and the lush tropical landscapes of the island. The atmosphere in Faie remains quiet and authentically Tahitian, largely untouched by large-scale tourism. Here, one can observe the traditional lifestyle of the islanders, who maintain a strong connection to their cultural heritage. Faie is a destination where legends feel alive, and the spiritual bond between the people and their environment is palpable in every corner.",
      es: "Faie es un pueblo de la isla de Huahine, situado en la costa noroeste. El asentamiento es conocido por sus tiendas de perlas y la producción de artesanía. Los aproximadamente 300 habitantes viven del turismo y la pesca. Faie cuenta con una pequeña marina para veleros. El entorno está caracterizado por plantaciones de cocoteros. Cerca hay un puente que conduce a la isla vecina de Huahine Nui.",
      pt: "Faie é uma aldeia na ilha de Huahine, situada na costa noroeste. O povoado é conhecido por suas lojas de pérolas e pela produção de artesanato. Os cerca de 300 habitantes vivem do turismo e da pesca. Faie possui uma pequena marina para barcos a vela. O entorno é caracterizado por plantações de coqueiros. Perto dali, há uma ponte que leva à ilha vizinha de Huahine Nui.",
      fr: "Faie est un village de l'île de Huahine, situé sur la côte nord-ouest. La localité est connue pour ses boutiques de perles et sa production artisanale. Les quelque 300 habitants vivent du tourisme et de la pêche. Faie dispose d'une petite marina pour les voiliers. Les environs sont marqués par des plantations de cocotiers. À proximité, un pont permet de rejoindre l'île voisine de Huahine Nui.",
    },
