      fr: ["Siège du musée de la mer de Ua Huka", "Connu pour des fouilles archéologiques datant du IVe siècle", "Célèbre pour la fabrication de modèles réduits de pirogues", "Situé au bord d'une baie pittoresque avec des falaises"],
