      hu: ["Hapatoni lakossága: kb. 150 fő (2020-as becslés)", "Faragott faajtók száma: 20", "Fekete homokos strand hossza: 300 m", "Régészeti temetkezési helyek száma: 5", "Templom építésének éve: 1878", "Távolság Vaitahutól: 3 km"],
