    imageHint: "Hanavave Bay of Virgins Fatu Hiva sunset",
    descriptionAdvanced: {
      de: "Hanavave ist ein abgelegenes und atemberaubend schönes Dorf an der Westküste der Insel Fatu Hiva, der südlichsten Insel der Marquesas. Es liegt am Ende der weltberühmten Bucht der Jungfrauen (Baie des Vierges), die oft als eine der schönsten Buchten der Welt bezeichnet wird. Die Bucht ist von massiven, fallusförmigen Vulkanfelsen umgeben, die im Abendlicht golden leuchten. Das Dorf selbst ist tief in der lokalen polynesischen Tradition verwurzelt. Hanavave ist das Hauptzentrum für die Herstellung von Tapa-Stoffen auf Fatu Hiva, einer traditionellen Rindenkleidung, die mit aufwendigen marquesanischen Motiven bemalt wird. Da es auf der Insel keinen Flugplatz gibt, ist Hanavave fast ausschließlich auf dem Seeweg erreichbar, was den authentischen und unberührten Charakter des Ortes bewahrt hat. Die Bewohner leben in Harmonie mit der Natur, umgeben von steilen Bergen und üppiger tropischer Vegetation, was Hanavave zu einem Traumziel für Segler und Abenteurer macht, die das wahre Polynesien suchen.",
      hu: "Hanavave egy távoli és lélegzetelállítóan szép falu Fatu Hiva nyugati partján, amely a Marquises-szigetek legdélebbi tagja. A település a világhírű Szüzek öble (Baie des Vierges) mélyén fekszik, amelyet gyakran a világ egyik legszebb öblének neveznek. Az öblöt hatalmas, fallikus alakú vulkáni sziklák veszik körül, amelyek az esti fényben aranyszínben ragyognak. Maga a falu mélyen gyökerezik a polinéz hagyományokban; Hanavave a tapa-szövet készítésének fő központja, ahol a hagyományos háncsruhát bonyolult márki-szigeteki motívumokkal díszítik. Mivel a szigeten nincs repülőtér, Hanavave szinte kizárólag a tenger felől közelíthető meg, ami segített megőrizni a hely eredeti és érintetlen jellegét. A lakosok szoros harmóniában élnek a természettel, meredek hegyek és buja trópusi növényzet ölelésében, így a falu a valódi Polinéziát kereső vitorlázók és kalandorok álomhelyszíne.",
      ro: "Hanavave este un sat izolat și de o frumusețe răpitoare situat pe coasta de vest a insulei Fatu Hiva, cea mai sudică din arhipelagul Marquesas. Localitatea se află la capătul celebrului Golf al Fecioarelor (Baie des Vierges), considerat adesea unul dintre cele mai frumoase din lume. Golful este flancat de formațiuni stâncoase vulcanice spectaculoase, cu forme falice, care capătă nuanțe aurii sub lumina apusului. Satul în sine păstrează cu sfințenie tradițiile polineziene; Hanavave este centrul principal pentru fabricarea pânzei tapa, o țesătură tradițională din scoarță de copac pictată cu motive complexe specifice insulelor Marquesas. Deoarece pe insulă nu există aeroport, Hanavave este accesibil aproape exclusiv pe mare, fapt ce a ajutat la conservarea caracterului său autentic și nealterat. Locuitorii duc o viață simplă în armonie cu natura, înconjurați de munți abrupți și vegetație tropicală luxuriantă, făcând din acest sat o destinație de vis pentru călătorii porniți în căutarea Polineziei veritabile.",
      en: "Hanavave is a remote and breathtakingly beautiful village on the west coast of Fatu Hiva, the southernmost island of the Marquesas. It sits at the head of the world-famous Bay of Virgins (Baie des Vierges), often cited as one of the most stunning bays on the planet. The bay is framed by massive, phallic-shaped volcanic rock formations that glow golden in the evening light. The village itself is deeply rooted in Polynesian tradition; Hanavave is the primary center for the production of Tapa cloth on Fatu Hiva, a traditional bark cloth painted with intricate Marquesan motifs. Since there is no airstrip on the island, Hanavave is accessible almost exclusively by sea, which has helped preserve its authentic and untouched character. The residents live in harmony with nature, surrounded by steep mountains and lush tropical greenery, making Hanavave a dream destination for sailors and adventurers seeking the true essence of Polynesia.",
      es: "Hanavave es un pueblo en la isla de Fatu Hiva, en las Marquesas, situado en la costa oeste. El asentamiento es conocido por sus dramáticas rocas de basalto y la Bahía de las Vírgenes (Baie des Vierges). Los aproximadamente 200 habitantes viven de la agricultura y el turismo. Hanavave tiene una pequeña iglesia y una tienda. La bahía es un destino popular para cruceros. El paisaje está marcado por acantilados escarpados.",
      pt: "Hanavave é uma aldeia na ilha de Fatu Hiva, nas Marquesas, situada na costa oeste. O assentamento é conhecido pelas suas dramáticas rochas de basalto e pela Baía das Virgens (Baie des Vierges). Os cerca de 200 habitantes vivem da agricultura e do turismo. Hanavave tem uma pequena igreja e uma loja. A baía é um destino popular para navios de cruzeiro. A paisagem é marcada por falésias íngremes.",
      fr: "Hanavave est un village de l'île de Fatu Hiva, aux Marquises, situé sur la côte ouest. La localité est célèbre pour ses pics de basalte spectaculaires et la Baie des Vierges. Les quelque 200 habitants vivent de l'agriculture et du tourisme. Hanavave dispose d'une petite église et d'un magasin. La baie est une escale prisée pour les navires de croisière. Le paysage est dominé par des falaises abruptes.",
    },
