      ro: ["Populația din Hanaiapa: aproximativ 100 (estimare 2020)", "Înălțimea celei mai mari cascade din apropiere: 50 m", "Numărul plantațiilor de banane: 8", "Distanța până la cea mai apropiată așezare mai mare (Atuona): 20 km", "Anul construirii capelei: 1930", "Panta medie a văilor: 15 grade"],
      en: ["Population of Hanaiapa: approx. 100 (2020 estimate)", "Height of the nearest large waterfall: 50 m", "Number of banana plantations: 8", "Distance to nearest larger settlement (Atuona): 20 km", "Year the chapel was built: 1930", "Average slope of the valleys: 15 degrees"],
      es: ["Población de Hanaiapa: aprox. 100 (estimación 2020)", "Altura de la cascada más grande cercana: 50 m", "Número de plantaciones de bananas: 8", "Distancia al asentamiento más cercano (Atuona): 20 km", "Año de construcción de la capilla: 1930", "Inclinación media de los valles: 15 grados"],
      pt: ["População de Hanaiapa: aprox. 100 (estimativa 2020)", "Altura da maior cascata nas proximidades: 50 m", "Número de plantações de banana: 8", "Distância do assentamento mais próximo (Atuona): 20 km", "Ano de construção da capela: 1930", "Inclinação média dos vales: 15 graus"],
      fr: ["Population de Hanaiapa : env. 100 (estimation 2020)", "Hauteur de la plus grande cascade à proximité : 50 m", "Nombre de plantations de bananes : 8", "Distance de la localité la plus proche (Atuona) : 20 km", "Année de construction de la chapelle : 1930", "Inclinaison moyenne des vallées : 15 degrés"],
