    imageHint: "Tetamanu old coral church Fakarava",
    descriptionAdvanced: {
      de: "Tetamanu ist ein kleines Dorf auf der Insel Fakarava in Französisch-Polynesien, das für seine traditionelle Lebensweise und die umliegenden Kokosplantagen bekannt ist. Es liegt an der Westküste des Atolls und ist ein beliebter Ausgangspunkt für Tauchausflüge zum Fakarava-Südpass, der für seine reiche Meeresfauna berühmt ist. Die Bevölkerung von etwa 100 Menschen lebt hauptsächlich von der Kopraproduktion und der Perlenzucht. Das Dorf verfügt über eine kleine Kirche, eine Schule und einen Laden. Die traditionelle Architektur der Häuser aus Palmblättern ist weitgehend erhalten. Tetamanu ist ein Beispiel für das ländliche Leben auf den Tuamotu-Inseln, das stark von den natürlichen Gegebenheiten geprägt ist.",
      hu: "Tetamanu egy apró falu, amely a Fakarava-atoll déli átjárójánál (Passé Sud) helyezkedik el, és fontos történelmi emlékeket őriz. Egykor ez a település volt az atoll fővárosa, mielőtt a közigazgatás Rotoavába költözött volna. A falu egyik legnevezetesebb látnivalója a Tuamotu-szigetek legrégebbi katolikus temploma, amely 1874-ben épült mészből és koralltömbökből. A templom egyszerű, de lenyűgöző architektúrája a misszionárius korszak stílusát idézi. Napjainkban Tetamanu elsősorban a búvárok körében világhírű, köszönhetően a közelben található 'cápa-falnak' (Wall of Sharks), ahol több száz szürke szirticápa gyűlik össze az erős áramlatokban. A falu csak hajóval érhető el, ami megőrizte annak nyugodt, távoli hangulatát. A látogatók számára a hely a polinéz történelem és a világ egyik legérintetlenebb tengeri ökoszisztémájának különleges találkozását kínálja.",
      ro: "Tetamanu este un sat mic situat la pasul de sud (Passé Sud) al atolului Fakarava, păstrând vestigii istorice importante. Odinioară, această așezare a fost capitala atolului înainte ca administrația să fie mutată la Rotoava. Una dintre cele mai remarcabile atracții ale satului este cea mai veche biserică catolică din Arhipelagul Tuamotu, construită în 1874 din var și blocuri de coral. Arhitectura simplă, dar impresionantă a bisericii evocă stilul epocii misionare. În prezent, Tetamanu este renumit în întreaga lume în rândul scafandrilor datorită 'zidului de rechini' aflat în apropiere, unde sute de rechini gri de recif se adună în curenții puternici. Satul este accesibil doar cu barca, ceea ce a contribuit la păstrarea atmosferei sale liniștite și izolate. Pentru vizitatori, locul reprezintă o întâlnire specială între istoria polineziană și unul dintre cele mai intacte ecosisteme marine din lume, oferind o experiență autentică în Pacificul de Sud.",
      en: "Tetamanu is a tiny village situated at the southern pass (Passé Sud) of the Fakarava atoll, holding significant historical importance as the former capital of the atoll. Before the administrative center moved to Rotoava, Tetamanu was the primary settlement in the region. Its most iconic landmark is the oldest Catholic church in the Tuamotu Archipelago, constructed in 1874 using lime and blocks of coral stone. This simple yet evocative structure stands as a testament to the early missionary period in French Polynesia. Today, Tetamanu is globally famous among diving enthusiasts for the nearby 'Wall of Sharks,' where hundreds of grey reef sharks congregate in the tidal currents of the pass. Accessible only by boat from Rotoava, the village maintains a serene, remote atmosphere. It offers a unique blend of Polynesian heritage and world-class marine biodiversity, making it a bucket-list destination for those seeking pristine natural beauty and quiet historical reflection.",
      es: "Tetamanu es un pequeño pueblo de la isla de Fakarava, en la Polinesia Francesa, conocido por su estilo de vida tradicional y los cocoteros que lo rodean. Se encuentra en la costa oeste del atolón y es un punto de partida popular para excursiones de buceo al paso sur de Fakarava, famoso por su rica fauna marina. La población de unos 100 habitantes vive principalmente de la producción de copra y el cultivo de perlas. El pueblo cuenta con una pequeña iglesia, una escuela y una tienda. La arquitectura tradicional de las casas de hojas de palma se conserva en gran medida. Tetamanu es un ejemplo de la vida rural en las islas Tuamotu, fuertemente marcada por las condiciones naturales.",
      pt: "Tetamanu é uma pequena aldeia na ilha de Fakarava, na Polinésia Francesa, conhecida pelo seu estilo de vida tradicional e pelos coqueirais circundantes. Situa-se na costa oeste do atol e é um ponto de partida popular para excursões de mergulho ao passo sul de Fakarava, famoso pela sua rica fauna marinha. A população de cerca de 100 pessoas vive principalmente da produção de copra e do cultivo de pérolas. A aldeia possui uma pequena igreja, uma escola e uma loja. A arquitetura tradicional das casas feitas de folhas de palmeira está em grande parte preservada. Tetamanu é um exemplo da vida rural nas ilhas Tuamotu, fortemente influenciada pelas condições naturais.",
      fr: "Tetamanu est un petit village sur l'île de Fakarava, en Polynésie française, réputé pour son mode de vie traditionnel et ses cocoteraies environnantes. Situé sur la côte ouest de l'atoll, c'est un point de départ prisé pour les sorties de plongée vers la passe sud de Fakarava, célèbre pour sa faune marine abondante. La population d'environ 100 personnes vit principalement de la production de coprah et de la perliculture. Le village dispose d'une petite église, d'une école et d'un magasin. L'architecture traditionnelle des maisons en palmes est largement préservée. Tetamanu est un exemple de la vie rurale dans les îles Tuamotu, fortement marquée par l'environnement naturel.",
    },
